import { useNavigate } from 'react-router-dom';
import { ChevronLeft } from 'lucide-react';
import { FlameIcon } from '../../components/icons';
import mascot from '../../assets/mascot.png';
import { useStreak } from '../../data';
import { useDietPageTracking, trackDietClick, DietPages } from '../../utils/tracking';

const WEEK = ['日', '一', '二', '三', '四', '五', '六'] as const;

/**
 * 打卡日历页（设计稿 1:1975）。
 * 暖色头 + 连续天数 + 吉祥物 + 月历（每日灰圆点；打卡日火苗；今天数字橙色）。
 * 当前为设计稿 mock（2025年12月，打卡 18 号，今天 23 号），接口接通后由 api/diet.ts 提供。
 */
export default function DietCalendar() {
  useDietPageTracking(DietPages.calendar);
  const navigate = useNavigate();
  const streakData = useStreak();

  // 展示当前月；打卡数据来自接口（check_in_dates → 本月打卡日；streak_days → 连续天数）
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth() + 1;
  const streak = streakData?.streak_days ?? 0;
  const today = now.getDate();
  const monthPrefix = `${year}-${String(month).padStart(2, '0')}-`;
  const checkedDays = new Set(
    (streakData?.check_in_dates ?? [])
      .filter((d) => d.startsWith(monthPrefix))
      .map((d) => Number(d.slice(monthPrefix.length, monthPrefix.length + 2))),
  );

  const firstWeekday = new Date(year, month - 1, 1).getDay(); // 0=日
  const daysInMonth = new Date(year, month, 0).getDate();
  const leading: (number | null)[] = Array.from({ length: firstWeekday }, () => null);
  const days: (number | null)[] = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const cells = [...leading, ...days];
  const trailingCount = (7 - (cells.length % 7)) % 7;
  const trailing = Array.from({ length: trailingCount }, (_, i) => -(i + 1)); // 负数=下月占位

  const allCells = [...cells, ...trailing];

  return (
    <div
      className="relative min-h-screen overflow-x-hidden"
      style={{
        background:
          'linear-gradient(180deg, #FCE0B8 0px, #FBEAD2 110px, #F4F0EA 240px, #F0F2F4 360px)',
      }}
    >
      <div className="relative" style={{ paddingTop: 'var(--status-bar-height, env(safe-area-inset-top, 0px))' }}>
        {/* 顶栏：仅返回 */}
        <header className="h-14">
          <button
            onClick={() => { trackDietClick(DietPages.calendar, 'back'); navigate(-1); }}
            className="grid h-9 w-9 place-items-center"
            style={{ marginLeft: 8, marginTop: 10 }}
            aria-label="返回"
          >
            <ChevronLeft size={22} className="text-[#1A1A1A]" />
          </button>
        </header>

        {/* 连续天数 + 吉祥物 */}
        <div className="relative px-6 pb-4">
          <div className="flex items-end gap-1">
            <span className="text-[72px] font-semibold leading-none text-[#2F2E2E]">{streak}</span>
            <span className="mb-2 text-lg font-semibold text-[#333333]">天</span>
          </div>
          <div className="mt-3 text-base font-semibold text-[#999999]">已连续记录</div>
          <img
            src={mascot}
            alt="吉祥物"
            className="absolute right-6 top-0 h-[123px] w-[104px] object-contain"
          />
        </div>

        {/* 月历卡 */}
        <section className="mx-[17px] rounded-xl bg-white px-4 pb-5 pt-4">
          {/* 月份切换 */}
          <div className="relative flex h-8 items-center justify-center">
            <button className="absolute left-0 grid h-6 w-6 place-items-center" aria-label="上个月">
              <ChevronLeft size={18} className="text-[#1A1A1A]" />
            </button>
            <span className="text-base font-semibold text-black">
              {year}年{month}月
            </span>
          </div>

          {/* 星期表头 */}
          <div className="mt-3 grid grid-cols-7">
            {WEEK.map((w) => (
              <div key={w} className="text-center text-sm text-[#757575]">
                {w}
              </div>
            ))}
          </div>

          {/* 日期网格 —— 点击跳回主页并切到那天 */}
          <div className="mt-2 grid grid-cols-7 gap-y-1">
            {allCells.map((d, i) => (
              <DayCell
                key={i}
                day={d}
                checked={d != null && d > 0 && checkedDays.has(d)}
                isToday={d === today}
                onPick={(day) => {
                  // 仅允许选当月已过/今天,未来日期由 DayCell disabled
                  const dateStr = `${monthPrefix}${String(day).padStart(2, '0')}`;
                  trackDietClick(DietPages.calendar, 'day', { date: dateStr });
                  navigate(`/?date=${dateStr}`);
                }}
              />
            ))}
          </div>
        </section>
      </div>
    </div>
  );
}

interface DayCellProps {
  readonly day: number | null;
  readonly checked: boolean;
  readonly isToday: boolean;
  readonly onPick: (day: number) => void;
}

function DayCell({ day, checked, isToday, onPick }: DayCellProps) {
  if (day == null) return <div className="h-[60px]" />;
  const nextMonth = day < 0;
  const label = nextMonth ? -day : day;

  return (
    <button
      onClick={() => !nextMonth && onPick(day)}
      className="flex h-[60px] flex-col items-center justify-start gap-1.5 pt-0.5"
      disabled={nextMonth}
    >
      <span
        className={
          nextMonth
            ? 'text-[15px] text-[#CCCCCC]'
            : isToday
              ? 'text-[15px] font-medium text-[#F76133]'
              : 'text-[15px] font-medium text-[#1A1A1A]'
        }
      >
        {label}
      </span>
      {!nextMonth &&
        (checked ? (
          <FlameIcon size={30} />
        ) : (
          <span className="h-[30px] w-[30px] rounded-full bg-[#ECECEC]" />
        ))}
    </button>
  );
}
