import { useCallback, useEffect, useState } from 'react';
import { dietApi, MEAL_SLOT_TO_TYPE } from './api/diet';
import type { FoodEntry, StreakData } from './api/diet';
import type { DailySummary, FoodRecord, MealGroup, MealType } from './types';
import { MOCK_DAILY_SUMMARY } from './mock';

/** 后端食物列表 → 按餐别聚合的 MealGroup[] */
function groupEntries(items: readonly FoodEntry[]): MealGroup[] {
  const order: MealType[] = ['breakfast', 'lunch', 'dinner', 'midnight'];
  const byMeal = new Map<MealType, FoodRecord[]>();
  for (const it of items) {
    const meal = MEAL_SLOT_TO_TYPE[it.meal_slot] ?? 'lunch';
    const rec: FoodRecord = {
      id: String(it.id),
      name: it.name,
      portion: '1份',
      calorie: Math.round(it.calories_kcal),
      imageUrl: it.image_thumb ?? undefined,
      macro: { carb: it.carbs, protein: it.protein, fat: it.fat },
    };
    const list = byMeal.get(meal) ?? [];
    list.push(rec);
    byMeal.set(meal, list);
  }
  return order
    .filter((m) => byMeal.has(m))
    .map((meal) => {
      const records = byMeal.get(meal)!;
      return {
        meal,
        records,
        totalCalorie: records.reduce((s, r) => s + r.calorie, 0),
        macro: records.reduce(
          (m, r) => ({
            carb: m.carb + (r.macro?.carb ?? 0),
            protein: m.protein + (r.macro?.protein ?? 0),
            fat: m.fat + (r.macro?.fat ?? 0),
          }),
          { carb: 0, protein: 0, fat: 0 },
        ),
      };
    });
}

/**
 * 主页数据：并行拉 board(环) + food-entries(分餐) + streak(连续天数)，
 * 映射为 DailySummary。后端不可用时回退 MOCK，保证 UI 始终可见。
 */
export function useHomeSummary(date: string) {
  const [data, setData] = useState<DailySummary | null>(null);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    // 每个接口独立 catch —— 之前 Promise.all 任一失败整页 fallback 到 mock,
    // 用户保存成功后主页还显示 mock 旧数据,看起来像「没刷新」
    const [board, entries, streak] = await Promise.all([
      dietApi.getBoard(date).catch((e) => {
        console.error('[diet] getBoard FAILED:', e);
        return null;
      }),
      dietApi.getFoodEntries(date).catch((e) => {
        console.error('[diet] getFoodEntries FAILED:', e);
        return null;
      }),
      dietApi.getStreak().catch(() => ({ streak_days: 0, check_in_dates: [] }) as StreakData),
    ]);
    if (!board) {
      // 只有 board 拿不到才回退 mock(连目标/总配额都没有);entries 拿不到就空餐
      setData(MOCK_DAILY_SUMMARY);
      setLoading(false);
      return;
    }
    const n = board.nutrients;
    setData({
      date,
      goalSet: board.target_calories > 0,
      statusText: board.status_text,
      statusType: board.status_type,
      progress: Math.max(0, Math.min(1, board.progress_percentage / 100)),
      remainingCalorie: Math.abs(Math.round(board.remaining_calories)),
      targetCalorie: Math.round(board.target_calories),
      intakeCalorie: Math.round(board.consumed_calories),
      burnedCalorie: Math.round(board.sports_calories),
      intakeMacro: { carb: n.carbs.consumed, protein: n.protein.consumed, fat: n.fat.consumed },
      targetMacro: { carb: n.carbs.target, protein: n.protein.target, fat: n.fat.target },
      streak: streak.streak_days,
      meals: entries ? groupEntries(entries.items) : [],
    });
    setLoading(false);
  }, [date]);

  useEffect(() => {
    load();
  }, [load]);

  return { data, loading, reload: load };
}

/** 打卡数据（日历用）。失败回退占位。 */
export function useStreak() {
  const [data, setData] = useState<StreakData | null>(null);
  useEffect(() => {
    dietApi
      .getStreak()
      .then(setData)
      .catch(() => setData({ streak_days: 3, check_in_dates: ['2026-06-03'] }));
  }, []);
  return data;
}
