import { useEffect, useState } from 'react';
import { X } from 'lucide-react';
import BottomSheet from './BottomSheet';
import type { MealType } from '../types';
import { MEAL_LABEL } from '../types';
import { trackEvent, ActionType, setCurrentPage } from '@/utils/tracker';
import { trackDietClick, DietPages } from '../utils/tracking';

interface ModifyTimeSheetProps {
  readonly open: boolean;
  /** 锚定的日期(YYYY-MM-DD),作为日期条的**最后一天**;默认选中也是它 */
  readonly anchorDate: string;
  /** 默认选中的餐别 */
  readonly initialMeal?: MealType;
  readonly onClose: () => void;
  readonly onConfirm: (date: string, meal: MealType) => void;
}

const MEALS: readonly MealType[] = ['breakfast', 'lunch', 'dinner', 'midnight'];
const WEEK_LABEL = ['日', '一', '二', '三', '四', '五', '六'] as const;

const fmtDate = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

/**
 * 修改记录时间弹层。日期条以 anchorDate 为最后一天,往前推 6 天共 7 天;
 * 默认选中最后一天(anchorDate)。月份动态展示当前选中日期所在月。
 */
export default function ModifyTimeSheet({ open, anchorDate, initialMeal = 'dinner', onClose, onConfirm }: ModifyTimeSheetProps) {
  // 用 anchorDate 当最后一天,生成往前 7 天(含 anchorDate)
  const anchor = new Date(anchorDate + 'T00:00:00');
  const days = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(anchor);
    d.setDate(anchor.getDate() - (6 - i));
    return d;
  });
  const [selDateStr, setSelDateStr] = useState<string>(anchorDate);
  const [meal, setMeal] = useState<MealType>(initialMeal);

  // 每次打开 / anchorDate 或 initialMeal 切换时,把 state 同步到默认值
  useEffect(() => {
    if (open) {
      setSelDateStr(anchorDate);
      setMeal(initialMeal);
    }
  }, [open, anchorDate, initialMeal]);

  // enter/exit 埋点
  useEffect(() => {
    if (!open) return;
    setCurrentPage(DietPages.timePicker);
    trackEvent(ActionType.ENTER, `${DietPages.timePicker}_enter`, DietPages.timePicker);
    return () => {
      trackEvent(ActionType.EXIT, `${DietPages.timePicker}_exit`, DietPages.timePicker);
    };
  }, [open]);

  const selDate = new Date(selDateStr + 'T00:00:00');
  const yearMonth = `${selDate.getFullYear()}年${selDate.getMonth() + 1}月`;

  return (
    <BottomSheet open={open} onClose={onClose}>
      <div className="px-5 pb-5 pt-4">
        <div className="mb-4 flex items-center justify-between">
          <span className="text-base font-semibold text-[#1A1A1A]">修改时间</span>
          <button onClick={onClose} aria-label="关闭">
            <X size={20} className="text-[#1A1A1A]" />
          </button>
        </div>

        <div className="mb-1 text-sm text-[#999]">{yearMonth}</div>
        <div className="mb-5 flex justify-between">
          {days.map((d) => {
            const dateStr = fmtDate(d);
            const isSel = dateStr === selDateStr;
            return (
              <button
                key={dateStr}
                onClick={() => { trackDietClick(DietPages.timePicker, 'day', { date: dateStr }); setSelDateStr(dateStr); }}
                className="flex flex-col items-center gap-1"
              >
                <span className="text-[11px] text-[#999]">{WEEK_LABEL[d.getDay()]}</span>
                <span
                  className={
                    isSel
                      ? 'grid h-9 w-9 place-items-center rounded-full text-sm font-medium text-white'
                      : 'grid h-9 w-9 place-items-center text-sm text-[#1A1A1A]'
                  }
                  style={isSel ? { background: 'linear-gradient(135deg,#FB8C18,#F75C36)' } : undefined}
                >
                  {d.getDate()}
                </span>
              </button>
            );
          })}
        </div>

        <div className="mb-6 grid grid-cols-4 gap-2">
          {MEALS.map((m) => (
            <button
              key={m}
              onClick={() => { trackDietClick(DietPages.timePicker, 'meal', { meal: m }); setMeal(m); }}
              className={
                m === meal
                  ? 'h-10 rounded-full bg-[#292F32] text-sm font-medium text-white'
                  : 'h-10 rounded-full bg-[#F4F5F6] text-sm text-[#1A1A1A]'
              }
            >
              {MEAL_LABEL[m]}
            </button>
          ))}
        </div>

        <div className="flex gap-3">
          <button onClick={() => { trackDietClick(DietPages.timePicker, 'cancel'); onClose(); }} className="h-12 flex-1 rounded-full border border-[#E5E6E8] text-sm font-medium text-[#1A1A1A]">
            取消
          </button>
          <button
            onClick={() => { trackDietClick(DietPages.timePicker, 'confirm', { date: selDateStr, meal }); onConfirm(selDateStr, meal); }}
            className="h-12 flex-1 rounded-full text-sm font-medium text-white"
            style={{ background: 'linear-gradient(90deg,#F75C36,#FB8C18)' }}
          >
            确认
          </button>
        </div>
      </div>
    </BottomSheet>
  );
}
