import axios from 'axios';
import type { AxiosResponse } from 'axios';
import { useUserStore } from '@/store/useUserStore';

/** 后端统一响应包。注意：多数接口 code=200 成功，save 接口用 code=0 成功。 */
export interface DietApiResponse<T> {
  readonly code: number;
  readonly message: string;
  readonly data: T;
}

/** 去掉尾部斜杠与 `/spark` 网关前缀 —— diet 独立服务路径是裸 `/api/...`，不走 spark 网关 */
function normalizeBase(u: string): string {
  return u.replace(/\/+$/, '').replace(/\/spark$/, '');
}

/**
 * diet 后端 baseURL 解析优先级：
 *   0. 本地 DEV 模式（vite dev server）→ 用相对路径 '/diet-function'，
 *      由 vite proxy 同源转发到 test.iwhop.cn，绕开测试后端不返 CORS 头。
 *   1. URL search 的 dietBase 参数（显式覆盖）
 *   2. VITE_DIET_API_BASE_URL（显式覆盖，env 文件 / 端侧注入）
 *   3. window.__SPARK_INIT__.baseUrl（端侧注入，去 /spark）
 *   4. VITE_API_BASE_URL（沿用主接口域名，去 /spark）
 *   5. 生产回退域名
 */
function resolveBaseURL(): string {
  // dev server 同源 proxy（避免浏览器跨域）
  if (import.meta.env.DEV) return '/diet-function';
  try {
    const fromQuery = new URLSearchParams(window.location.search).get('dietBase');
    if (fromQuery) return decodeURIComponent(fromQuery).replace(/\/+$/, '');
  } catch {
    // ignore
  }
  const dietEnv = import.meta.env.VITE_DIET_API_BASE_URL as string | undefined;
  if (dietEnv) return dietEnv.replace(/\/+$/, '');
  const fromWindow = (window as unknown as { __SPARK_INIT__?: { baseUrl?: string } }).__SPARK_INIT__?.baseUrl;
  if (fromWindow) return normalizeBase(fromWindow);
  const fromEnv = import.meta.env.VITE_API_BASE_URL as string | undefined;
  if (fromEnv) return normalizeBase(fromEnv);
  return 'https://micro-life.iwhop.cn';
}

/**
 * diet 后端鉴权方式（2026-06-18 文档更新后确认）：
 *   token 直接作为 user_id 字段传 —— body 里 `"user_id": "<JWT>"`，
 *   GET path 里 `/api/.../{<JWT>}`。后端从 token 解析 userId，无需 Authorization 头。
 *
 * 取 token 优先级：
 *   1. URL ?token=...（主 App 打开 H5 时注入；PC dev 联调时手动拼）。
 *      支持两种位置：
 *        a) HashRouter URL `http://x/#/?token=...` —— `?` 在 `#` 之后，需从 hash 里解析
 *        b) 普通 search `http://x/?token=...#/`   —— 直接 window.location.search
 *      解析后缓存到 localStorage，跨刷新存活
 *   2. localStorage 缓存的 token
 *   3. window.__SPARK_INIT__.token（端侧 document_start 注入）
 *   4. useUserStore.token（兼容老的 spark 流程）
 */
const DIET_TOKEN_KEY = 'diet-token';

function readTokenFromUrl(): string {
  // a) search 段
  try {
    const fromSearch = new URLSearchParams(window.location.search).get('token');
    if (fromSearch) return fromSearch;
  } catch {
    // ignore
  }
  // b) hash 内的 ? query（HashRouter 形式 `#/?token=...`）
  try {
    const h = window.location.hash || '';
    const qIdx = h.indexOf('?');
    if (qIdx >= 0) {
      const fromHash = new URLSearchParams(h.slice(qIdx + 1)).get('token');
      if (fromHash) return fromHash;
    }
  } catch {
    // ignore
  }
  return '';
}

export function readDietToken(): string {
  // 0. DEV 模式下预置 token 永远最高优先级 —— 即使 URL ?token= 注入了别的 token
  //    （Android 容器 attachToken 会把主 App microLife token 拼到 URL，但 diet 测试库
  //    不一定认那个 userId，所以联调时永远用 .env.development.local 里的预置）。
  if (import.meta.env.DEV) {
    const preset = import.meta.env.VITE_DIET_DEV_TOKEN;
    if (preset) return preset;
  }
  const fromUrl = readTokenFromUrl();
  if (fromUrl) {
    try { localStorage.setItem(DIET_TOKEN_KEY, fromUrl); } catch { /* ignore */ }
    return fromUrl;
  }
  try {
    const cached = localStorage.getItem(DIET_TOKEN_KEY);
    if (cached) return cached;
  } catch {
    // ignore
  }
  const fromInit = (window as unknown as { __SPARK_INIT__?: { token?: string } }).__SPARK_INIT__?.token;
  if (fromInit) return fromInit;
  return useUserStore.getState().token ?? '';
}

/**
 * PC 浏览器调试自动取 token —— 模仿福利社 `useUserStore.mintDevToken`：
 *   1. 优先用 `VITE_DIET_DEV_TOKEN`（diet 测试库已注册用户的预置 token）
 *   2. 没配 token 才 fallback 走 microLife `/user/login`
 *      ⚠️ 注意：microLife 登录返回的 token userId 是真实账号 ID，
 *      diet 测试库可能没这个用户 → 接口会返「用户不存在」404。
 *
 * 真实容器（iOS WKUserScript / Android attachToken）会预先注入 token，本函数 noop。
 * 生产构建 import.meta.env.DEV === false，整段逻辑会被 tree-shake 掉。
 */
export async function ensureDietDevToken(): Promise<void> {
  if (!import.meta.env.DEV) return;
  // URL 带 ?dietreset=1 强制清缓存（用于真机调试时 localStorage 残留旧 token 导致 404）
  try {
    const hasReset =
      new URLSearchParams(window.location.search).get('dietreset') === '1' ||
      new URLSearchParams((window.location.hash.split('?')[1] ?? '')).get('dietreset') === '1';
    if (hasReset) {
      localStorage.removeItem(DIET_TOKEN_KEY);
    }
  } catch {
    // ignore
  }
  // 1) 预置 token（推荐）—— DEV 下永远以 env 为准，自动覆盖 localStorage 里的旧 token，
  //    避免 PC 之前 mint 的过期 token 残留到真机 dev URL 模式
  const preset = import.meta.env.VITE_DIET_DEV_TOKEN;
  if (preset) {
    try {
      if (localStorage.getItem(DIET_TOKEN_KEY) !== preset) {
        localStorage.setItem(DIET_TOKEN_KEY, preset);
      }
    } catch { /* ignore */ }
    return;
  }

  if (readDietToken()) return;

  // 2) microLife 登录 fallback
  const account = import.meta.env.VITE_DIET_DEV_ACCOUNT;
  const password = import.meta.env.VITE_DIET_DEV_PASSWORD;
  if (!account || !password) return;
  try {
    const res = await axios.post<{ code: number; data: { token: string } }>(
      `${resolveMicroLifeBase()}/user/login`,
      { account, password, phoneModel: 'PC-Debug', networkEnv: 'wifi', ip: '127.0.0.1' },
      { timeout: 15000 },
    );
    const token = res.data?.data?.token;
    if (token) {
      localStorage.setItem(DIET_TOKEN_KEY, token);
    }
  } catch {
    // 静默失败 —— 没拿到就走 mock 回退，跟以前行为一致
  }
}

/**
 * diet 接口的 user_id 字段值 —— 文档约定就是 token 字符串本身。
 * 无 token 时回退到 deviceId/'1'（仅供本地未登录时占位，会被后端 401）。
 */
export function getDietUserId(): string {
  return readDietToken() || useUserStore.getState().deviceId || '1';
}

/**
 * microLife 主后端 base（文件上传接口在此，与 diet 服务不同域）：
 *   test: test-ai-howear.iwhop.cn/howeartest/microLife
 *   prod: micro-life.iwhop.cn/microLife
 * 可用 ?microLifeBase / VITE_MICROLIFE_BASE_URL 覆盖。
 */
export function resolveMicroLifeBase(): string {
  try {
    const q = new URLSearchParams(window.location.search).get('microLifeBase');
    if (q) return decodeURIComponent(q).replace(/\/+$/, '');
  } catch {
    // ignore
  }
  const override = import.meta.env.VITE_MICROLIFE_BASE_URL as string | undefined;
  if (override) return override.replace(/\/+$/, '');
  return import.meta.env.VITE_ENV === 'production'
    ? 'https://micro-life.iwhop.cn/microLife'
    : 'https://test-ai-howear.iwhop.cn/howeartest/microLife';
}

const dietClient = axios.create({
  baseURL: resolveBaseURL(),
  timeout: 30000, // 识别/AI 接口耗时较长
  headers: { 'Content-Type': 'application/json' },
});

// 鉴权完全走 body 的 user_id 字段（见 getDietUserId 注释），无需在 header 塞 token。

dietClient.interceptors.response.use((response: AxiosResponse<DietApiResponse<unknown>>) => {
  const body = response.data;
  // code 200 与 0 均视为成功（后端不同接口口径不一）
  if (body && (body.code === 200 || body.code === 0)) {
    return { ...response, data: body.data };
  }
  // 失败：保留 message + 原始 body 供调用方判断（如识别失败的 error_detail）
  const err = new Error(body?.message || '请求失败') as Error & { body?: unknown };
  err.body = body;
  return Promise.reject(err);
});

export default dietClient;
