import { useEffect, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { ChevronLeft, ChevronDown, ChevronRight, Flame, Soup } from 'lucide-react';
import CalorieRing from '../../components/CalorieRing';
import { SettingHexIcon, CtaTextIcon, CtaCameraIcon } from '../../components/icons';
import MacroGrid from '../../components/MacroGrid';
import RecordSheet from '../../components/RecordSheet';
import RecordEditSheet from '../../components/RecordEditSheet';
import ModifyTimeSheet from '../../components/ModifyTimeSheet';
import CustomCalorieSheet from '../../components/CustomCalorieSheet';
import mascot from '../../assets/mascot.png';
import { goBack as nativeGoBack } from '@/utils/bridge';
import { useHomeSummary } from '../../data';
import { useDietPageTracking, trackDietClick, DietPages } from '../../utils/tracking';
import { dietApi } from '../../api/diet';
import { MOCK_DAILY_SUMMARY, MOCK_EMPTY_SUMMARY } from '../../mock';
import { MEAL_LABEL } from '../../types';
import type { FoodRecord, MealGroup } from '../../types';

const WEEK = ['日', '一', '二', '三', '四', '五', '六'] as const;

/**
 * 饮食热量功能主页（今日热量汇总）。
 * 设计稿 node 1:2957。当前用 MOCK_DAILY_SUMMARY，接口接通后由 api/diet.ts 提供。
 */
export default function DietHome() {
  useDietPageTracking(DietPages.home);
  const navigate = useNavigate();
  const [params] = useSearchParams();
  // ⚠️ 必须用本地时间格式化,不能用 toISOString —— UTC 偏移会让中国时区少一天
  const fmt = (d: Date) =>
    `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  const todayDate = new Date();
  const today = fmt(todayDate);

  // ?date=YYYY-MM-DD 支持从日历页或他处跳回时切到那一天
  const urlDate = params.get('date');
  const isValidDate = (s: string | null): s is string => !!s && /^\d{4}-\d{2}-\d{2}$/.test(s);
  const [selectedDate, setSelectedDate] = useState<string>(isValidDate(urlDate) ? urlDate : today);
  useEffect(() => {
    if (isValidDate(urlDate) && urlDate !== selectedDate) setSelectedDate(urlDate);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [urlDate]);

  const { data: loaded, reload } = useHomeSummary(selectedDate);
  const data = params.get('empty') ? MOCK_EMPTY_SUMMARY : loaded ?? MOCK_DAILY_SUMMARY;
  const ready = !!loaded || !!params.get('empty');

  // 本周 7 天(本周日 → 本周六,WEEK = ['日','一'...'六'] 顺序对齐)
  // 星期条永远展示「本周」(基准是 today,不随 selectedDate 漂)
  const weekStart = new Date(todayDate);
  weekStart.setDate(todayDate.getDate() - todayDate.getDay());
  weekStart.setHours(0, 0, 0, 0);
  const weekDates = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(weekStart);
    d.setDate(weekStart.getDate() + i);
    return fmt(d);
  });
  const activeWeekday = weekDates.indexOf(selectedDate); // -1 = selectedDate 不在本周

  const isToday = selectedDate === today;
  // 用 fmt 出的字符串构造 Date 必须显式 T00:00:00 强制本地时间
  const selDate = new Date(selectedDate + 'T00:00:00');
  const headerTitle = isToday ? '今天' : `${selDate.getMonth() + 1}月${selDate.getDate()}日`;

  // 弹层状态
  const [recordOpen, setRecordOpen] = useState(false);
  const [recordMode, setRecordMode] = useState<'photo' | 'text'>('photo');
  const [editGroup, setEditGroup] = useState<MealGroup | null>(null);
  const [modifyOpen, setModifyOpen] = useState(false);
  const [customOpen, setCustomOpen] = useState(false);
  // ModifyTimeSheet 修改后的待保存日期/餐别(null = 用默认: date=selectedDate, meal='dinner')
  const [pendingRecordDate, setPendingRecordDate] = useState<string | null>(null);
  const [pendingRecordMeal, setPendingRecordMeal] = useState<import('../../types').MealType | null>(null);

  // 滚动到 hero 卡片下方后,顶栏吸顶 加底色
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 56);
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const openRecord = (mode: 'photo' | 'text') => {
    trackDietClick(DietPages.home, mode);
    setRecordMode(mode);
    setRecordOpen(true);
  };
  // 点某条记录 → 打开所在餐的编辑弹层
  const handleEditRecord = (r: FoodRecord) => {
    trackDietClick(DietPages.home, 'meal', { recordId: r.id });
    const g = data.meals.find((m) => m.records.some((x) => x.id === r.id)) ?? null;
    setEditGroup(g);
  };
  const progress = data.progress;

  return (
    <div
      className="relative min-h-screen"
      style={{
        background:
          'linear-gradient(180deg, #F6D2A8 0px, #F9E8D0 64px, #F8E9D6 120px, #F3EFEA 280px, #F1F3F5 420px, #F0F2F4 560px)',
      }}
    >
      {/* sticky 顶部条 —— 状态栏 padding + header 合并到一个 sticky 容器,
          这样滚动吸顶时整个上半部分(含状态栏区域)都被背景色覆盖,不再透出内容 */}
      <div
        className="sticky top-0 z-20 transition-colors duration-200"
        style={{
          paddingTop: 'var(--status-bar-height, env(safe-area-inset-top, 0px))',
          background: scrolled ? 'rgba(246,210,168,0.92)' : 'transparent',
          backdropFilter: scrolled ? 'blur(8px)' : 'none',
          WebkitBackdropFilter: scrolled ? 'blur(8px)' : 'none',
          boxShadow: scrolled ? '0 1px 0 rgba(0,0,0,0.04)' : 'none',
        }}
      >
        <header className="relative h-14">
          <button
            onClick={() => { trackDietClick(DietPages.home, 'back'); nativeGoBack(); }}
            className="absolute left-2 top-1/2 grid h-9 w-9 -translate-y-1/2 place-items-center"
            aria-label="返回"
          >
            <ChevronLeft size={22} className="text-[#1A1A1A]" />
          </button>
          <button
            onClick={() => { trackDietClick(DietPages.home, 'calendar'); navigate('/calendar'); }}
            className="absolute left-1/2 top-1/2 flex -translate-x-1/2 -translate-y-1/2 items-center gap-1"
          >
            <span className="text-lg font-semibold text-black">{headerTitle}</span>
            <ChevronDown size={16} className="text-[#999999]" />
          </button>
          <div className="absolute right-2 top-1/2 flex -translate-y-1/2 items-center gap-1">
            <button
              onClick={() => { trackDietClick(DietPages.home, 'streak'); navigate('/calendar'); }}
              className="flex items-center gap-1 rounded-full px-3 py-1.5"
              style={{ background: 'linear-gradient(90deg,#F75C36,#FB8C18)' }}
            >
              <Flame size={12} className="text-white" fill="currentColor" />
              <span className="text-xs font-semibold text-white">已打卡{data.streak}天</span>
            </button>
            <button onClick={() => { trackDietClick(DietPages.home, 'setting'); setCustomOpen(true); }} className="grid h-9 w-9 place-items-center" aria-label="设置">
              <SettingHexIcon size={20} className="text-[#333333]" />
            </button>
          </div>
        </header>
      </div>

      {/* 星期条 —— 点击切换到该天,未来日期禁用 */}
        <div className="flex items-center justify-between px-5 py-3">
          {WEEK.map((w, i) => {
            const dateStr = weekDates[i];
            const isFuture = dateStr > today;
            const isSelected = i === activeWeekday;
            return (
              <button
                key={w}
                onClick={() => { if (!isFuture) { trackDietClick(DietPages.home, 'week', { date: dateStr }); setSelectedDate(dateStr); } }}
                disabled={isFuture}
                className={
                  isSelected
                    ? 'grid h-8 w-8 place-items-center rounded-lg bg-[#FA7D22] text-sm font-medium text-white'
                    : isFuture
                      ? 'grid h-8 w-8 place-items-center text-sm text-[#CCCCCC]'
                      : 'grid h-8 w-8 place-items-center text-sm text-[#666666]'
                }
              >
                {w}
              </button>
            );
          })}
        </div>

        {/* 接口首次未返回前整体淡出,避免 mock 数字闪到真值 */}
        <div
          className="transition-opacity duration-200"
          style={{ opacity: ready ? 1 : 0 }}
        >
        {!data.goalSet ? (
          <HomeEmpty onSetGoal={() => { trackDietClick(DietPages.home, 'setGoal'); navigate('/goal'); }} />
        ) : (
        <>
        {/* 今日汇总卡：按设计稿 1:2957 坐标绝对定位（卡内相对） */}
        <section className="relative mx-3 rounded-xl bg-white" style={{ height: 307 }}>
          {/* 热量圈 @(93,24) 180x180 */}
          <div className="absolute" style={{ left: 93, top: 24 }}>
            <CalorieRing progress={progress}>
              <span className="text-sm font-medium text-[#A1A1AA]">{data.statusText} (千卡)</span>
              <span className="my-1 text-[40px] font-extrabold leading-none text-[#18181B]">
                {data.remainingCalorie}
              </span>
              <span className="rounded-full bg-[#F5F6F6] px-3 py-1 text-[11px] text-[#A1A1AA]">
                自定义预算 {data.targetCalorie}
              </span>
            </CalorieRing>
          </div>
          {/* 饮食摄入圆 @(16,144) / 运动消耗圆 @(276,144) */}
          <div className="absolute" style={{ left: 16, top: 144 }}>
            <SideStat label="饮食摄入" value={data.intakeCalorie} />
          </div>
          <div className="absolute" style={{ left: 276, top: 144 }}>
            <SideStat label="运动消耗" value={data.burnedCalorie} />
          </div>
          {/* 三宫格 @(16,228) 334 宽 */}
          <div className="absolute" style={{ left: 16, top: 228, width: 334 }}>
            <MacroGrid
              cells={[
                { label: '碳水', value: `${data.intakeMacro.carb}/${data.targetMacro.carb}克` },
                { label: '蛋白质', value: `${data.intakeMacro.protein}/${data.targetMacro.protein}克` },
                { label: '脂肪', value: `${data.intakeMacro.fat}/${data.targetMacro.fat}克` },
              ]}
            />
          </div>
        </section>

        {/* 分餐记录;pb 留给底部固定 CTA(高 ~80px),不能太大 */}
        <div className="px-3 pb-24 pt-3">
          {data.meals.length === 0 ? (
            <EmptyRecords />
          ) : (
            data.meals.map((m) => <MealCard key={m.meal} group={m} onEdit={handleEditRecord} />)
          )}
        </div>
        </>
        )}
        </div>

      {/* 底部双 CTA */}
      <div
        className="fixed inset-x-0 bottom-0 z-10 flex gap-3 bg-gradient-to-t from-[#F0F2F4] px-4 pt-3"
        style={{ paddingBottom: 'calc(env(safe-area-inset-bottom) + 16px)' }}
      >
        <button
          onClick={() => openRecord('text')}
          className="flex h-12 flex-1 items-center justify-center gap-2 rounded-full bg-[#292F32] text-sm font-medium text-white"
        >
          <CtaTextIcon size={20} />
          文字输入
        </button>
        <button
          onClick={() => openRecord('photo')}
          className="flex h-12 flex-1 items-center justify-center gap-2 rounded-full text-sm font-medium text-white"
          style={{ background: 'linear-gradient(90deg,#F75C36,#FB8C18)' }}
        >
          <CtaCameraIcon size={20} />
          拍照输入
        </button>
      </div>

      {/* 记录饮食弹层（拍照/手动） */}
      <RecordSheet
        open={recordOpen}
        initialMode={recordMode}
        date={pendingRecordDate ?? selectedDate}
        mealSlot={pendingRecordMeal ?? 'dinner'}
        onClose={() => {
          setRecordOpen(false);
          setPendingRecordDate(null);
          setPendingRecordMeal(null);
        }}
        onConfirm={() => {
          setRecordOpen(false);
          setPendingRecordDate(null);
          setPendingRecordMeal(null);
          reload();
        }}
        onModifyTime={() => setModifyOpen(true)}
      />
      {/* 记录编辑弹层 */}
      <RecordEditSheet
        open={editGroup != null}
        group={editGroup}
        date={data.date.replace(/-/g, '.')}
        onClose={() => setEditGroup(null)}
        onDelete={async () => {
          if (editGroup) {
            const ids = editGroup.records.map((r) => Number(r.id)).filter((n) => Number.isFinite(n));
            if (ids.length) await dietApi.deleteRecord(ids).catch(() => undefined);
          }
          setEditGroup(null);
          reload();
        }}
      />
      {/* 修改时间弹层 —— anchorDate 用主页当前选中日期作最后一天; 确认后写入 pending,
          RecordSheet 用它做 saveRecord 的 record_date / meal_slot */}
      <ModifyTimeSheet
        open={modifyOpen}
        anchorDate={pendingRecordDate ?? selectedDate}
        initialMeal={pendingRecordMeal ?? 'dinner'}
        onClose={() => setModifyOpen(false)}
        onConfirm={(date, meal) => {
          setPendingRecordDate(date);
          setPendingRecordMeal(meal);
          setModifyOpen(false);
        }}
      />
      {/* 自定义热量弹层（设置入口） */}
      <CustomCalorieSheet
        open={customOpen}
        onClose={() => setCustomOpen(false)}
        onSave={async (v) => {
          await dietApi.updateGoalCalories(v).catch(() => undefined);
          setCustomOpen(false);
          reload();
        }}
      />
    </div>
  );
}

function SideStat({ label, value }: { readonly label: string; readonly value: number }) {
  return (
    <div className="flex h-[74px] w-[74px] flex-col items-center justify-center rounded-full border-[1.5px] border-[#EAEBED]">
      <span className="text-[10px] text-[#71717A]">{label}</span>
      <span className="mt-0.5 text-base font-bold text-[#333333]">{value}</span>
    </div>
  );
}

function MealCard({ group, onEdit }: { readonly group: MealGroup; readonly onEdit: (r: FoodRecord) => void }) {
  return (
    <section className="mb-3 rounded-xl bg-white px-3 pb-4 pt-3">
      <div className="flex items-center justify-between px-1">
        <span className="text-sm font-medium text-black">{MEAL_LABEL[group.meal]}</span>
        <div className="flex items-center gap-1">
          <span className="text-base font-bold text-[#2F2E2E]">{group.totalCalorie}</span>
          <span className="text-xs text-[#A1A1AA]">kcal</span>
          <ChevronRight size={14} className="text-[#A1A1AA]" />
        </div>
      </div>

      <div className="mt-2">
        {group.records.map((r) => (
          <button
            key={r.id}
            onClick={() => onEdit(r)}
            className="flex w-full items-center gap-3 py-3 text-left"
          >
            <div className="h-16 w-16 shrink-0 overflow-hidden rounded-xl bg-[#F0F0F0]">
              {r.imageUrl ? <img src={r.imageUrl} alt={r.name} className="h-full w-full object-cover" /> : null}
            </div>
            <div className="min-w-0 flex-1">
              <div className="truncate text-base font-medium text-[#2F2E2E]">{r.name}</div>
              <div className="mt-1 text-xs text-[#A1A1AA]">{r.portion}</div>
            </div>
            <div className="flex items-center gap-1">
              <span className="text-base font-bold text-[#2F2E2E]">{r.calorie}</span>
              <span className="text-xs text-[#A1A1AA]">kcal</span>
              <ChevronRight size={14} className="text-[#A1A1AA]" />
            </div>
          </button>
        ))}
      </div>

      <div className="mt-2">
        <MacroGrid
          cells={[
            { label: '碳水', value: `${group.macro.carb}克` },
            { label: '蛋白质', value: `${group.macro.protein}克` },
            { label: '脂肪', value: `${group.macro.fat}克` },
          ]}
        />
      </div>
    </section>
  );
}

/** 主页空态（未设目标）：吉祥物问候卡 + 暂无记录占位（设计稿 1:294） */
function HomeEmpty({ onSetGoal }: { readonly onSetGoal: () => void }) {
  return (
    <div className="px-3 pb-40">
      <button onClick={onSetGoal} className="flex w-full items-center gap-3 rounded-xl bg-white p-4 text-left">
        <img src={mascot} alt="" className="h-10 w-10 shrink-0 object-contain" />
        <span className="text-sm leading-relaxed text-[#1A1A1A]">
          你好！欢迎来到健康世界～还没有设定目标吗？一起设定一个健康目标吧。
        </span>
      </button>
      <div className="mt-3">
        <EmptyRecords />
      </div>
    </div>
  );
}

/** 暂无记录占位卡 */
function EmptyRecords() {
  return (
    <div className="flex flex-col items-center rounded-xl bg-white py-12">
      <Soup size={46} className="text-[#F9C3B0]" />
      <div className="mt-3 text-sm font-medium text-[#1A1A1A]">暂无记录</div>
      <div className="mt-1 text-xs text-[#BDBDBD]">没有找到最近60天的饮食记录哦</div>
    </div>
  );
}
