import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { X } from 'lucide-react';
import { dietApi } from '../../api/diet';
import type { ProfileSubmit } from '../../api/diet';
import { useDietPageTracking, trackDietClick, DietPages } from '../../utils/tracking';

type Gender = 'male' | 'female';

const ACTIVITY_MAP: Readonly<Record<string, ProfileSubmit['activity_level']>> = {
  久坐: 'sedentary',
  轻度活动: 'light',
  中度活动: 'moderate',
  高强度: 'active',
};
const GOAL_MAP: Readonly<Record<string, ProfileSubmit['goal_type']>> = { 减脂: 'Cutting', 保持: 'Maintain', 增肌: 'Bulking' };

/**
 * 设定目标-填写身体信息（设计稿 1:1666/1:1729）。两步表单。
 * 第一步：性别/年龄/身高/体重；第二步：运动量/目标/理想体重/期望达成日期。
 * 数字输入校验：年龄0-100、身高140-200、体重30-100、理想体重30-100。
 */
export default function GoalInfo() {
  useDietPageTracking(DietPages.goalInfo);
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [gender, setGender] = useState<Gender>('female');
  const [age, setAge] = useState('');
  const [height, setHeight] = useState('');
  const [weight, setWeight] = useState('');
  const [activity, setActivity] = useState('中度活动');
  const [target, setTarget] = useState('减脂');
  const [idealWeight, setIdealWeight] = useState('');
  const [dueDate, setDueDate] = useState('');

  const step1Valid = age !== '' && height !== '' && weight !== '';

  // step2 确认 → 提交身体数据/目标，再进每日目标页（后端不可用时也照常进入）
  const submitAndNext = async () => {
    try {
      await dietApi.submitProfile({
        confirm: false,
        sex: gender,
        age: Number(age),
        height: Number(height),
        current_weight_kg: Number(weight),
        activity_level: ACTIVITY_MAP[activity] ?? 'light',
        goal_type: GOAL_MAP[target] ?? 'Cutting',
        goal_weight_kg: Number(idealWeight) || Number(weight),
        target_date: dueDate || '',
      });
    } catch {
      // 忽略，仍进入每日目标页
    }
    navigate('/goal/daily');
  };

  return (
    <div
      className="relative min-h-screen overflow-x-hidden"
      style={{ background: 'linear-gradient(180deg,#FCE0B8 0px,#FBEAD2 120px,#F4F0EA 220px,#F0F2F4 320px)' }}
    >
      <div style={{ paddingTop: 'var(--status-bar-height, env(safe-area-inset-top, 0px))' }}>
        <button onClick={() => { trackDietClick(DietPages.goalInfo, 'close'); navigate('/'); }} className="grid h-9 w-9 place-items-center" style={{ marginLeft: 8, marginTop: 10 }} aria-label="关闭">
          <X size={22} className="text-[#1A1A1A]" />
        </button>

        <div className="px-6 pb-5 pt-1">
          <h1 className="text-2xl font-bold leading-snug text-[#1A1A1A]">
            30秒填写基本信息
            <br />
            让我更了解你
          </h1>
          <p className="mt-2 text-sm text-[#999]">信息安全保护中，请放心填写</p>
        </div>

        <section className="min-h-[60vh] rounded-t-[20px] bg-white px-6 pb-32 pt-6">
          {step === 1 ? (
            <div className="space-y-5">
              <Field label="性别">
                <div className="flex gap-3">
                  <Segment active={gender === 'male'} onClick={() => { trackDietClick(DietPages.goalInfo, 'gender', { gender: 'male' }); setGender('male'); }}>男</Segment>
                  <Segment active={gender === 'female'} onClick={() => { trackDietClick(DietPages.goalInfo, 'gender', { gender: 'female' }); setGender('female'); }}>女</Segment>
                </div>
              </Field>
              <Field label="年龄">
                <NumInput value={age} onChange={setAge} placeholder="点击输入年龄" unit="岁" />
              </Field>
              <Field label="身高">
                <NumInput value={height} onChange={setHeight} placeholder="点击输入身高" unit="cm" />
              </Field>
              <Field label="体重">
                <NumInput value={weight} onChange={setWeight} placeholder="点击输入体重" unit="kg" />
              </Field>
            </div>
          ) : (
            <div className="space-y-5">
              <Field label="平时运动量如何">
                <PickRow value={activity} options={['久坐', '轻度活动', '中度活动', '高强度']} onChange={setActivity} />
              </Field>
              <Field label="您的目标是">
                <PickRow value={target} options={['减脂', '保持', '增肌']} onChange={setTarget} />
              </Field>
              <Field label="理想体重">
                <NumInput value={idealWeight} onChange={setIdealWeight} placeholder="点击输入理想体重" unit="kg" />
              </Field>
              <Field label="您的期望达成日期是">
                <input
                  value={dueDate}
                  onChange={(e) => setDueDate(e.target.value)}
                  placeholder="点击选择日期"
                  className="h-12 w-full rounded-xl border border-[#EEF0F2] px-4 text-[15px] text-[#1A1A1A] outline-none placeholder:text-[#BDBDBD]"
                />
              </Field>
            </div>
          )}
        </section>
      </div>

      {/* 底部操作 */}
      <div className="fixed inset-x-0 bottom-0 bg-white px-6 pt-2" style={{ paddingBottom: 'calc(env(safe-area-inset-bottom) + 16px)' }}>
        <div className="mb-3 text-center text-sm text-[#999]">
          暂不填写 <button onClick={() => { trackDietClick(DietPages.goalInfo, 'skip'); navigate('/'); }} className="text-[#F76133]">跳过</button>
        </div>
        <div className="flex gap-3">
          <button
            onClick={() => { trackDietClick(DietPages.goalInfo, 'back', { step }); step === 1 ? navigate('/') : setStep(1); }}
            className="h-12 flex-1 rounded-full border border-[#E5E6E8] text-sm font-medium text-[#1A1A1A]"
          >
            {step === 1 ? '返回' : '上一步'}
          </button>
          <button
            onClick={() => { trackDietClick(DietPages.goalInfo, step === 1 ? 'next' : 'confirm'); step === 1 ? setStep(2) : submitAndNext(); }}
            disabled={step === 1 && !step1Valid}
            className="h-12 flex-1 rounded-full text-sm font-medium text-white transition-opacity disabled:opacity-50"
            style={{ background: 'linear-gradient(90deg,#F75C36,#FB8C18)' }}
          >
            {step === 1 ? '下一步' : '确认'}
          </button>
        </div>
      </div>
    </div>
  );
}

function Field({ label, children }: { readonly label: string; readonly children: React.ReactNode }) {
  return (
    <div>
      <div className="mb-2 text-[15px] font-semibold text-[#1A1A1A]">{label}</div>
      {children}
    </div>
  );
}

function Segment({ active, onClick, children }: { readonly active: boolean; readonly onClick: () => void; readonly children: React.ReactNode }) {
  return (
    <button
      onClick={onClick}
      className={
        active
          ? 'h-12 flex-1 rounded-xl bg-[#292F32] text-[15px] font-medium text-white'
          : 'h-12 flex-1 rounded-xl bg-[#F4F5F6] text-[15px] text-[#1A1A1A]'
      }
    >
      {children}
    </button>
  );
}

function NumInput({ value, onChange, placeholder, unit }: { readonly value: string; readonly onChange: (v: string) => void; readonly placeholder: string; readonly unit: string }) {
  return (
    <div className="flex h-12 items-center rounded-xl border border-[#EEF0F2] px-4">
      <input
        value={value}
        onChange={(e) => onChange(e.target.value.replace(/[^0-9]/g, ''))}
        inputMode="numeric"
        placeholder={placeholder}
        className="flex-1 text-[15px] text-[#1A1A1A] outline-none placeholder:text-[#BDBDBD]"
      />
      <span className="text-[15px] text-[#999]">{unit}</span>
    </div>
  );
}

function PickRow({ value, options, onChange }: { readonly value: string; readonly options: readonly string[]; readonly onChange: (v: string) => void }) {
  return (
    <div className="flex flex-wrap gap-2">
      {options.map((o) => (
        <button
          key={o}
          onClick={() => onChange(o)}
          className={
            o === value
              ? 'rounded-full bg-[#292F32] px-4 py-2 text-sm text-white'
              : 'rounded-full bg-[#F4F5F6] px-4 py-2 text-sm text-[#1A1A1A]'
          }
        >
          {o}
        </button>
      ))}
    </div>
  );
}
