interface MacroCell {
  readonly label: string;
  readonly value: string;
}

interface MacroGridProps {
  readonly cells: readonly MacroCell[];
}

/**
 * 三大营养素网格。设计稿：三个等宽块，底 #F4F6F8 r8，标签 10/#71717A，值 16/700 #27272A。
 */
export default function MacroGrid({ cells }: MacroGridProps) {
  return (
    <div className="flex gap-[6px]">
      {cells.map((c) => (
        <div key={c.label} className="flex-1 rounded-lg bg-[#F4F6F8] px-3 pt-3 pb-3">
          <div className="text-[10px] leading-none text-[#71717A]">{c.label}</div>
          <div className="mt-1.5 whitespace-nowrap text-base font-bold text-[#27272A]">{c.value}</div>
        </div>
      ))}
    </div>
  );
}
