export function installDevMock(): void {
  const params = new URLSearchParams(window.location.search);
  const envLocal = import.meta.env.VITE_ENV === 'local';
  // 默认走真后端；显式 `?mock=1` 才开 mock（接口未就绪 / 离线开发场景）。
  const enabled = params.get('mock') === '1';
  if (!envLocal || !enabled) return;

  const MOCKS = buildMocks();
  const OrigXHR = window.XMLHttpRequest;

  function MockXHR(this: XMLHttpRequest) {
    const xhr = new OrigXHR();
    let mockedKey: string | null = null;
    const origOpen = xhr.open.bind(xhr);
    const origSend = xhr.send.bind(xhr);

    xhr.open = function (method: string, url: string, ...rest: unknown[]) {
      for (const k of Object.keys(MOCKS)) {
        if (url && url.includes(k)) {
          mockedKey = k;
          break;
        }
      }
      return (origOpen as unknown as (...args: unknown[]) => void)(method, url, ...rest);
    } as XMLHttpRequest['open'];

    xhr.send = function (body?: Document | XMLHttpRequestBodyInit | null) {
      if (mockedKey) {
        const payload = JSON.stringify(MOCKS[mockedKey]);
        setTimeout(() => {
          Object.defineProperty(xhr, 'readyState', { value: 4, configurable: true });
          Object.defineProperty(xhr, 'status', { value: 200, configurable: true });
          Object.defineProperty(xhr, 'responseText', { value: payload, configurable: true });
          Object.defineProperty(xhr, 'response', { value: payload, configurable: true });
          xhr.getResponseHeader = (n: string) =>
            n.toLowerCase() === 'content-type' ? 'application/json' : null;
          xhr.getAllResponseHeaders = () => 'content-type: application/json\r\n';
          xhr.dispatchEvent(new Event('readystatechange'));
          xhr.dispatchEvent(new Event('load'));
          xhr.dispatchEvent(new Event('loadend'));
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const anyXhr = xhr as any;
          if (typeof anyXhr.onreadystatechange === 'function') anyXhr.onreadystatechange();
          if (typeof anyXhr.onload === 'function') anyXhr.onload();
        }, 10);
        return;
      }
      return origSend(body ?? null);
    } as XMLHttpRequest['send'];

    return xhr;
  }
  MockXHR.prototype = OrigXHR.prototype;
  window.XMLHttpRequest = MockXHR as unknown as typeof XMLHttpRequest;

  // eslint-disable-next-line no-console
  console.info('[devMock] XHR mock installed for', Object.keys(MOCKS).length, 'endpoints');
}
