import axios from 'axios';
import dietClient, { getDietUserId, resolveMicroLifeBase } from './client';
import { useUserStore } from '@/store/useUserStore';
import type { MealType } from '../types';

/** 文件上传返回项（microLife /file/videoOrPicture/upload） */
export interface UploadedFile {
  readonly fileUrl: string;
  readonly fileName: string;
  readonly fileSize: number;
  readonly fileCoverUrl: string | null;
}

/** 后端餐次枚举 ↔ 前端 MealType */
export const MEAL_SLOT_TO_TYPE: Readonly<Record<string, MealType>> = {
  breakfast: 'breakfast',
  lunch: 'lunch',
  dinner: 'dinner',
  late_snack: 'midnight',
};
export const MEAL_TYPE_TO_SLOT: Readonly<Record<MealType, string>> = {
  breakfast: 'breakfast',
  lunch: 'lunch',
  dinner: 'dinner',
  midnight: 'late_snack',
};

// ── 首页概览 ──────────────────────────────
export interface NutrientCell {
  readonly label: string;
  readonly consumed: number;
  readonly target: number;
  readonly unit: string;
}
export interface BoardData {
  readonly status_text: string;
  readonly status_type: 'normal' | 'exceeded';
  readonly target_calories: number;
  readonly consumed_calories: number;
  readonly remaining_calories: number;
  readonly sports_calories: number;
  readonly progress_percentage: number;
  readonly nutrients: { readonly carbs: NutrientCell; readonly protein: NutrientCell; readonly fat: NutrientCell };
}

// ── 食物记录 ──────────────────────────────
export interface FoodEntry {
  readonly id: number;
  readonly name: string;
  readonly calories_kcal: number;
  readonly record_date: string;
  readonly meal_slot: string;
  readonly weight_g: number;
  readonly carbs: number;
  readonly protein: number;
  readonly fat: number;
  readonly source: string;
  readonly image_thumb: string | null;
}
export interface FoodEntriesData {
  readonly record_date: string;
  readonly total_kcal: number;
  readonly meal_count: number;
  readonly total_carbs: number;
  readonly total_protein: number;
  readonly total_fat: number;
  readonly items: readonly FoodEntry[];
}

// ── AI 识别 / 对话 结果 ───────────────────
export interface RecognizedFood {
  readonly food_name: string;
  readonly serving_size?: string;
  readonly calories_kcal: number;
  readonly weight_g: number;
  readonly carbs_g: number;
  readonly protein_g: number;
  readonly fat_g: number;
  readonly image_url?: string;
}
export interface RecognizeResult {
  readonly id: number;
  readonly total_nutrition: {
    readonly total_weight_g: number;
    readonly total_calories_kcal: number;
    readonly total_carbs_g: number;
    readonly total_protein_g: number;
    readonly total_fat_g: number;
  };
  readonly foods: readonly RecognizedFood[];
}

// ── 目标设置 ──────────────────────────────
export interface ProfilePlan {
  readonly weekly_change_kg: number;
  readonly daily_calorie_adjustment_kcal: number;
  readonly recommended_daily_intake_kcal: number;
  readonly expected_weight_loss_kg: number;
}
export interface ProfileWarning {
  readonly code: string;
  readonly level: 'error' | 'info' | 'warning';
  readonly message: string;
  readonly requires_confirm: boolean;
}
export interface ProfileResult {
  readonly warnings: readonly ProfileWarning[];
  readonly bmi: number;
  readonly bmr_kcal: number;
  readonly maintenance_kcal: number;
  readonly adjusted_plan: ProfilePlan;
  readonly desired_plan: ProfilePlan;
  readonly safety_flags: readonly string[];
}
export interface ProfileSubmit {
  readonly confirm: boolean;
  readonly sex: 'male' | 'female';
  readonly age: number;
  readonly height: number;
  readonly current_weight_kg: number;
  readonly activity_level: 'sedentary' | 'light' | 'moderate' | 'active';
  readonly goal_type: 'Bulking' | 'Cutting' | 'Maintain';
  readonly goal_weight_kg: number;
  readonly target_date: string;
}
export interface ProfileDisplay {
  readonly user_profile: {
    readonly age: number;
    readonly height_cm: number;
    readonly current_weight_kg: number;
    readonly target_weight_kg: number;
    readonly goal_type: string;
    readonly activity_level: string;
    readonly target_date: string;
  };
  readonly bmi_analysis: { readonly value: number; readonly status: string; readonly status_label: string };
  readonly recommendation: {
    readonly daily_calories_kcal: number;
    readonly nutrients: { readonly carbohydrates_g: number; readonly protein_g: number; readonly fat_g: number };
  };
}

export interface OnboardingStatus {
  readonly user_id: string;
  readonly is_first_time: boolean;
  readonly profile: unknown;
}

export interface StreakData {
  readonly streak_days: number;
  readonly check_in_dates: readonly string[];
}

export interface SaveFoodItem {
  readonly food_name: string;
  readonly calories_kcal: number;
  readonly weight_g: number;
  readonly carbs: number;
  readonly protein: number;
  readonly fat: number;
  /** 拍照识别的食物图 URL,后端字段名是 image_thumb,主页列表展示用 */
  readonly image_thumb?: string;
}

/** diet 全部接口。失败由 client 拦截器统一 reject（携带 body 供判断 error_detail）。 */
export const dietApi = {
  getBoard: async (date: string, sportsCalories = 0): Promise<BoardData> => {
    const res = await dietClient.post<BoardData>('/api/user/board', {
      user_id: getDietUserId(),
      date,
      sports_calories: sportsCalories,
    });
    return (res.data as unknown as { board: BoardData }).board;
  },

  getFoodEntries: async (recordDate: string): Promise<FoodEntriesData> => {
    const res = await dietClient.get<FoodEntriesData>(`/api/diet/food-entries/${getDietUserId()}`, {
      params: { record_date: recordDate },
    });
    return res.data;
  },

  getStreak: async (): Promise<StreakData> => {
    const res = await dietClient.get<StreakData>(`/api/user/check-in/streak/${getDietUserId()}`);
    return res.data;
  },

  getOnboardingStatus: async (): Promise<OnboardingStatus> => {
    const res = await dietClient.get<OnboardingStatus>(`/api/user/onboarding-status/${getDietUserId()}`);
    return res.data;
  },

  /**
   * 保存/检测身体数据 + 目标（一个接口两用，文档约定 PUT）。
   *   confirm=false → 仅做合理性检测，不写库，返回 warnings/safety_flags + adjusted_plan/desired_plan
   *   confirm=true  → 检测通过后写库
   */
  submitProfile: async (payload: ProfileSubmit): Promise<ProfileResult> => {
    const res = await dietClient.put<ProfileResult>('/api/user/profile', { user_id: getDietUserId(), ...payload });
    return res.data;
  },

  getProfileDisplay: async (): Promise<ProfileDisplay> => {
    const res = await dietClient.get<ProfileDisplay>(`/api/user/profile/display/${getDietUserId()}`);
    return res.data;
  },

  updateGoalCalories: async (customCaloriesKcal: number): Promise<void> => {
    await dietClient.post('/api/user/goal/update', { user_id: getDietUserId(), custom_calories_kcal: customCaloriesKcal });
  },

  /**
   * 上传图片到 microLife，返回可访问的 fileUrl（再传给识别接口）。
   * 接口：POST {microLifeBase}/file/videoOrPicture/upload (multipart/form-data)
   * 返回：{ code:200, data:[{ fileUrl, ... }] }
   */
  uploadImage: async (file: File | Blob, fileName = 'food.jpg'): Promise<string> => {
    const form = new FormData();
    form.append('file', file, file instanceof File ? file.name : fileName);
    form.append('isGenerateCover', 'false');
    const { token } = useUserStore.getState();
    const res = await axios.post<{ code: number; msg: string; data: UploadedFile[] }>(
      `${resolveMicroLifeBase()}/file/videoOrPicture/upload`,
      form,
      { timeout: 60000, headers: token ? { token } : undefined },
    );
    const url = res.data?.data?.[0]?.fileUrl;
    if (res.data?.code !== 200 || !url) throw new Error(res.data?.msg || '上传失败');
    return url;
  },

  /**
   * 图片识别。先 uploadImage 上传到 microLife 拿 fileUrl，再传 image_url 给后端识别。
   * 识别失败后端返回 code!=200，会被拦截器 reject（body.error_detail 含提示文案）。
   */
  recognizeImage: async (imageUrl: string): Promise<RecognizeResult> => {
    const res = await dietClient.post<RecognizeResult>('/api/diet/recognize', {
      image_url: imageUrl,
      user_id: getDietUserId(),
    });
    return res.data;
  },

  /** AI 文本对话识别。失败时 code=200 但 data.status='failed'，需调用方判断。 */
  dietChat: async (content: string, timestamp: string): Promise<RecognizeResult | { status: 'failed'; display_text: string }> => {
    const res = await dietClient.post('/api/ai/diet-chat', { user_id: getDietUserId(), content, timestamp });
    return res.data as RecognizeResult | { status: 'failed'; display_text: string };
  },

  saveRecord: async (payload: {
    readonly record_date: string;
    readonly meal_slot: string;
    readonly source: 'manual' | 'recognize' | 'chat';
    readonly ai_chat_id?: number;
    readonly foods: readonly SaveFoodItem[];
  }): Promise<{ readonly record_ids: readonly number[] }> => {
    const res = await dietClient.post('/api/diet/save', { user_id: getDietUserId(), ...payload });
    return res.data as { record_ids: readonly number[] };
  },

  /** 修改记录的餐别（可批量）。文档：POST + body { user_id, record_ids[], meal_slot }。 */
  updateRecord: async (recordIds: readonly number[], mealSlot: string): Promise<{ readonly record_ids: readonly number[] }> => {
    const res = await dietClient.post('/api/diet/update', {
      user_id: getDietUserId(),
      record_ids: recordIds,
      meal_slot: mealSlot,
    });
    return res.data as { record_ids: readonly number[] };
  },

  /** 删除记录（可批量）。文档：POST + body { user_id, record_ids[] }。 */
  deleteRecord: async (recordIds: readonly number[]): Promise<{ readonly record_ids: readonly number[] }> => {
    const res = await dietClient.post('/api/diet/delete', {
      user_id: getDietUserId(),
      record_ids: recordIds,
    });
    return res.data as { record_ids: readonly number[] };
  },

  /** 快捷建议（chips）。⚠️ 后端 openapi 未声明此接口，可能尚未实现；保留以备后续。 */
  getSuggestion: async (promptType: 'daily_advice' | 'nutrition_analysis' | 'recipe'): Promise<string> => {
    const res = await dietClient.post<{ reply_text: string }>('/api/ai/suggestion', {
      user_id: getDietUserId(),
      prompt_type: promptType,
    });
    return (res.data as unknown as { reply_text: string }).reply_text;
  },
};
