/**
 * 饮食热量模块共享数据类型。字段名/类型遵循 api-contract.md，后端接口对齐后直接复用。
 */

/** 餐别：早餐/午餐/晚餐/夜宵 */
export type MealType = 'breakfast' | 'lunch' | 'dinner' | 'midnight';

/** 三大营养素（克），值为「已摄入/目标」时分别存 intake/target */
export interface Macro {
  readonly carb: number;
  readonly protein: number;
  readonly fat: number;
}

/** 单条食物记录 */
export interface FoodRecord {
  readonly id: string;
  readonly name: string;
  /** 份量描述，如 "1份" */
  readonly portion: string;
  readonly calorie: number;
  /** 缩略图 URL，可空 */
  readonly imageUrl?: string;
  readonly macro?: Macro;
}

/** 一餐（同餐别下的多条记录聚合） */
export interface MealGroup {
  readonly meal: MealType;
  readonly totalCalorie: number;
  readonly records: readonly FoodRecord[];
  readonly macro: Macro;
}

/** 某一天的饮食热量汇总（主页数据） */
export interface DailySummary {
  /** YYYY-MM-DD */
  readonly date: string;
  /** 是否已设定目标。未设定 → 主页展示空态（问候卡 + 暂无记录） */
  readonly goalSet: boolean;
  /** 环中心状态文案：还可以吃 / 多吃了 */
  readonly statusText: string;
  /** normal=未超标（橙环）/ exceeded=超标（红环） */
  readonly statusType: 'normal' | 'exceeded';
  /** 环填充比例 0~1（后端 progress_percentage/100） */
  readonly progress: number;
  /** 还可以吃（千卡） = 目标 - 已摄入 + 运动消耗 */
  readonly remainingCalorie: number;
  /** 目标/预算（千卡） */
  readonly targetCalorie: number;
  /** 饮食摄入（千卡） */
  readonly intakeCalorie: number;
  /** 运动消耗（千卡） */
  readonly burnedCalorie: number;
  /** 当日三大营养素：intake=已摄入，target=目标 */
  readonly intakeMacro: Macro;
  readonly targetMacro: Macro;
  /** 连续打卡天数 */
  readonly streak: number;
  readonly meals: readonly MealGroup[];
}

export const MEAL_LABEL: Readonly<Record<MealType, string>> = {
  breakfast: '早餐',
  lunch: '午餐',
  dinner: '晚餐',
  midnight: '夜宵',
};
