import { motion } from 'framer-motion';
import { useTranslation } from 'react-i18next';
import MarqueeText from './MarqueeText';

interface LoadingProps {
  readonly text?: string;
}

export default function Loading({ text }: LoadingProps) {
  const { t } = useTranslation();
  const display = text ?? t('common.loading');
  return (
    <div className="flex flex-col items-center justify-center py-20 gap-3">
      <motion.div
        className="w-8 h-8 rounded-full border-3 border-spark-orange/30 border-t-spark-orange"
        animate={{ rotate: 360 }}
        transition={{ duration: 0.8, repeat: Infinity, ease: 'linear' }}
        style={{ borderWidth: 3 }}
      />
      <MarqueeText className="text-sm text-gray-400" style={{ maxWidth: '80%', justifyContent: 'center' }}>
        {display}
      </MarqueeText>
    </div>
  );
}
