import { useEffect, useState } from 'react';
import { X } from 'lucide-react';
import BottomSheet from './BottomSheet';
import { trackEvent, ActionType, setCurrentPage } from '@/utils/tracker';
import { trackDietClick, DietPages } from '../utils/tracking';

interface CustomCalorieSheetProps {
  readonly open: boolean;
  readonly onClose: () => void;
  readonly onSave: (value: number) => void;
}

/**
 * 自定义热量值弹层（设计稿 1:2414）。输入热量值，范围 800-4000 千卡校验。
 */
export default function CustomCalorieSheet({ open, onClose, onSave }: CustomCalorieSheetProps) {
  const [value, setValue] = useState('');
  const num = Number(value);
  const valid = value !== '' && num >= 800 && num <= 4000;

  useEffect(() => {
    if (!open) return;
    setCurrentPage(DietPages.customCalorie);
    trackEvent(ActionType.ENTER, `${DietPages.customCalorie}_enter`, DietPages.customCalorie);
    return () => {
      trackEvent(ActionType.EXIT, `${DietPages.customCalorie}_exit`, DietPages.customCalorie);
    };
  }, [open]);

  const save = () => {
    if (!valid) return;
    trackDietClick(DietPages.customCalorie, 'save', { value: num });
    onSave(num);
    setValue('');
    onClose();
  };

  return (
    <BottomSheet open={open} onClose={onClose}>
      <div className="px-5 pb-5 pt-4">
        <div className="mb-4 flex items-center justify-between">
          <span className="text-base font-semibold text-[#1A1A1A]">自定义热量值</span>
          <button onClick={() => { trackDietClick(DietPages.customCalorie, 'close'); onClose(); }} aria-label="关闭">
            <X size={20} className="text-[#1A1A1A]" />
          </button>
        </div>

        <div className="flex h-12 items-center rounded-xl border border-[#EEF0F2] px-4">
          <input
            value={value}
            onChange={(e) => setValue(e.target.value.replace(/[^0-9]/g, ''))}
            onClick={(e) => e.currentTarget.focus()}
            onTouchEnd={(e) => (e.currentTarget as HTMLInputElement).focus()}
            inputMode="numeric"
            autoComplete="off"
            placeholder="请输入热量值"
            className="flex-1 text-[15px] text-[#1A1A1A] outline-none placeholder:text-[#BDBDBD]"
          />
          <span className="text-[15px] text-[#999]">千卡</span>
        </div>
        <p className="mt-2 text-xs text-[#999]">可设置范围800-4000千卡</p>

        <button
          onClick={save}
          disabled={!valid}
          className="mt-5 h-12 w-full rounded-full text-sm font-medium text-white transition-opacity disabled:opacity-50"
          style={{ background: 'linear-gradient(90deg,#F75C36,#FB8C18)' }}
        >
          保存
        </button>
      </div>
    </BottomSheet>
  );
}
