import i18n from '../locales';

/**
 * Native bridge for hybrid WebView.
 *
 * 兼容模式：
 * - Android: `window.NativeBridge.xxx()` —— 通过 `WebView.addJavascriptInterface` 注入
 * - iOS:     `window.webkit.messageHandlers.xxx.postMessage(payload)` —— WKScriptMessageHandler
 * - 兜底:    `window.ReactNativeWebView.postMessage(JSON.stringify(...))` —— RN 环境
 *
 * Native 通过调用 `window.__onXxx` 全局回调函数返回事件（参考 test-collection 实现）。
 */

interface NativeBridgeApi {
  readonly showRewardAd?: (payload?: string) => void;
  readonly goBack?: () => void;
  readonly vibrate?: (pattern?: string) => void;
  readonly share?: (payload: string) => void;
  readonly navigate?: (payload: string) => void;
  readonly openLocalH5?: (path: string) => void;
  /** 触发微信授权，native 通过 window.__onWxAuthResult / __onWxAuthFail 回传 */
  readonly wxLogin?: () => void;
  /** 切换宿主底部 tab，0=首页/1=视频/2=中间福利/3=设备/4=我的 */
  readonly switchTab?: (index: number) => void;
  /** 拉起微信"商家转账确认收款"原生页（OpenSDK WXOpenBusinessView，businessType=requestMerchantTransfer） */
  readonly startMerchantTransfer?: (payload: string) => void;
}

interface WebkitHandler {
  readonly postMessage: (payload: unknown) => void;
}

interface WebkitMessageHandlers {
  readonly [key: string]: WebkitHandler | undefined;
}

declare global {
  interface Window {
    NativeBridge?: NativeBridgeApi;
    webkit?: { messageHandlers?: WebkitMessageHandlers };
    ReactNativeWebView?: { postMessage: (msg: string) => void };
    __onRewardAdShow?: (() => void) | null;
    __onRewardAdClick?: (() => void) | null;
    __onRewardAdResult?: ((rewarded: boolean) => void) | null;
    __onRewardAdFail?: ((msg: string) => void) | null;
    /**
     * Native 直发 /ad-report 后回传的金币数（绕开 H5 进程被回收的问题）。
     * H5 收到后可以跳过自己的 reportWithRetry，直接展示奖励。仅 Android 实现。
     */
    __onRewardAdSettled?: ((coinsRewarded: number) => void) | null;
    __onWxAuthResult?: ((code: string) => void) | null;
    __onWxAuthFail?: ((msg: string) => void) | null;
    /** 微信"商家转账确认收款"返回回调；errCode：0=用户已确认；其它=取消/失败/异常 */
    __onMerchantTransferResp?: ((errCode: number, errMsg: string) => void) | null;
  }
}

/** 当前是否处于原生容器内（Android/iOS/RN 任一） */
export function isInApp(): boolean {
  if (typeof window === 'undefined') return false;
  return (
    !!window.NativeBridge ||
    !!window.webkit?.messageHandlers?.showRewardAd ||
    !!window.ReactNativeWebView
  );
}

/* ─── 激励视频广告 ─── */

export interface RewardAdHandlers {
  readonly onShow?: () => void;
  /**
   * 用户点击广告(广告内可点击区域 → 跳广告主落地页 / 唤起 deeplink) 触发。
   * 来自 ATSDK rewardedVideoDidClick / onRewardedVideoAdPlayClicked。
   */
  readonly onClick?: () => void;
  readonly onResult: (rewarded: boolean) => void;
  readonly onFail?: (msg: string) => void;
  /**
   * Native 直发 /ad-report 成功后通知（仅 Android）。回调里可以直接拿到金币数，
   * 不必再走 reportWithRetry。如果设了这个 handler，watchAd 会优先用它结束流程。
   */
  readonly onSettled?: (coinsRewarded: number) => void;
}

/**
 * 触发原生激励视频广告。
 *
 * 使用示例:
 * ```ts
 * showRewardAd({
 *   onShow: () => console.log('ad shown'),
 *   onResult: (rewarded) => {
 *     if (rewarded) adReport(adToken);
 *   },
 *   onFail: (msg) => showToast(`广告加载失败: ${msg}`),
 * });
 * ```
 *
 * @param handlers 回调集合（Native 通过 `window.__onXxx` 调用）
 * @param adToken 可选，后端签发的广告 Token，传递给 Native 以便回调时回传
 */
export function showRewardAd(handlers: RewardAdHandlers, adToken?: string): void {
  if (typeof window === 'undefined') {
    handlers.onFail?.('not in browser');
    return;
  }

  const cleanup = () => {
    window.__onRewardAdShow = null;
    window.__onRewardAdClick = null;
    window.__onRewardAdResult = null;
    window.__onRewardAdFail = null;
    window.__onRewardAdSettled = null;
  };

  window.__onRewardAdShow = () => {
    handlers.onShow?.();
  };

  window.__onRewardAdClick = () => {
    handlers.onClick?.();
  };

  window.__onRewardAdResult = (rewarded: boolean) => {
    // 注意：这里不调 cleanup，因为 native 可能后续再触发 __onRewardAdSettled。
    // 由 watchAd 自己根据 settled 状态决定何时清理。
    handlers.onResult(rewarded);
  };

  window.__onRewardAdFail = (msg: string) => {
    cleanup();
    handlers.onFail?.(msg);
  };

  window.__onRewardAdSettled = (coinsRewarded: number) => {
    cleanup();
    handlers.onSettled?.(coinsRewarded);
  };

  const payload = adToken ?? '';

  if (window.NativeBridge?.showRewardAd) {
    window.NativeBridge.showRewardAd(payload);
    return;
  }

  if (window.webkit?.messageHandlers?.showRewardAd) {
    window.webkit.messageHandlers.showRewardAd.postMessage({ adToken: payload });
    return;
  }

  if (window.ReactNativeWebView) {
    window.ReactNativeWebView.postMessage(
      JSON.stringify({ type: 'showAd', data: { adType: 'reward', adToken: payload } }),
    );
    return;
  }

  // 浏览器环境下 5 秒后模拟成功，便于本地调试
  cleanup();
  setTimeout(() => handlers.onResult(true), 1500);
}

/* ─── 其他桥方法（保留兼容） ─── */

export function navigateTo(route: string, params?: Record<string, unknown>): void {
  const payload = { route, params };
  if (window.NativeBridge?.navigate) {
    window.NativeBridge.navigate(JSON.stringify(payload));
    return;
  }
  if (window.webkit?.messageHandlers?.navigate) {
    window.webkit.messageHandlers.navigate.postMessage(payload);
    return;
  }
  if (window.ReactNativeWebView) {
    window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'navigate', data: payload }));
  }
}

/**
 * 打开本地 H5（走原生 LocalH5Activity），目前用于跳转到 test-collection 三个测试子页。
 * path 形如 "h5/test-collection/index.html#/sbti" / "#/bazi" / "#/dream"。
 * 非 App 环境（浏览器直接调试）降级为 window.open。
 */
export function openLocalH5(path: string): void {
  if (window.NativeBridge?.openLocalH5) {
    window.NativeBridge.openLocalH5(path);
    return;
  }
  if (window.webkit?.messageHandlers?.openLocalH5) {
    window.webkit.messageHandlers.openLocalH5.postMessage(path);
    return;
  }
  // 浏览器 fallback：拼出 dev 路径，不一定能打开（本地没 asset 映射），但方便排查
  window.open(path.replace(/^h5\/(.+?)\/index\.html/, '/$1/'), '_blank');
}

export function share(title: string, content: string, url?: string): void {
  const payload = { title, content, url };
  if (window.NativeBridge?.share) {
    window.NativeBridge.share(JSON.stringify(payload));
    return;
  }
  if (window.webkit?.messageHandlers?.share) {
    window.webkit.messageHandlers.share.postMessage(payload);
    return;
  }
  if (window.ReactNativeWebView) {
    window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'share', data: payload }));
  }
}

export function vibrate(pattern?: 'light' | 'medium' | 'heavy'): void {
  const p = pattern ?? 'light';
  if (window.NativeBridge?.vibrate) {
    window.NativeBridge.vibrate(p);
    return;
  }
  if (window.webkit?.messageHandlers?.vibrate) {
    window.webkit.messageHandlers.vibrate.postMessage({ pattern: p });
    return;
  }
  if (window.ReactNativeWebView) {
    window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'vibrate', data: { pattern: p } }));
  }
}

/**
 * 触发微信授权。Native 要求：
 * - 调 WeChat SDK 发起 code 授权
 * - 成功：调用 window.__onWxAuthResult(code)
 * - 失败：调用 window.__onWxAuthFail(msg)
 * 60s 无响应自动按失败处理（避免按钮死卡在"授权中"）。
 */
export function wxLogin(): Promise<string> {
  return new Promise((resolve, reject) => {
    let settled = false;
    const cleanup = () => {
      window.__onWxAuthResult = null;
      window.__onWxAuthFail = null;
      clearTimeout(timer);
    };
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(new Error(i18n.t('errors.wxAuthTimeout')));
    }, 60_000);
    window.__onWxAuthResult = (code: string) => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve(code);
    };
    window.__onWxAuthFail = (msg: string) => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(new Error(msg || i18n.t('errors.wxAuthFailed')));
    };

    if (window.NativeBridge?.wxLogin) {
      window.NativeBridge.wxLogin();
      return;
    }
    if (window.webkit?.messageHandlers?.wxLogin) {
      window.webkit.messageHandlers.wxLogin.postMessage({});
      return;
    }
    settled = true;
    cleanup();
    reject(new Error(i18n.t('errors.wxAuthNotSupported')));
  });
}

/**
 * 拉起微信"商家转账确认收款"原生页：
 * - native 调 OpenSDK WXOpenBusinessView.Req(businessType="requestMerchantTransfer", query=<query>)
 *   query 是后端 detail 接口直接拼好的 URL string：mchId=xxx&appId=xxx&package=<urlEncoded>
 * - 用户在微信里点确认 → native 通过 window.__onMerchantTransferResp(errCode, errMsg) 回传
 * - errCode=0 表示用户已确认（不等于资金到账，最终态来自后端 notify_url 回调，前端再轮询 detail）
 * 60s 超时按用户取消处理
 */
export function startMerchantTransfer(payload: { appId: string; query: string }): Promise<{ errCode: number; errMsg: string }> {
  return new Promise((resolve, reject) => {
    let settled = false;
    const cleanup = () => {
      window.__onMerchantTransferResp = null;
      clearTimeout(timer);
    };
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(new Error(i18n.t('errors.wxConfirmTimeout')));
    }, 60_000);
    window.__onMerchantTransferResp = (errCode: number, errMsg: string) => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve({ errCode, errMsg: errMsg ?? '' });
    };

    const json = JSON.stringify(payload);
    if (window.NativeBridge?.startMerchantTransfer) {
      window.NativeBridge.startMerchantTransfer(json);
      return;
    }
    if (window.webkit?.messageHandlers?.startMerchantTransfer) {
      window.webkit.messageHandlers.startMerchantTransfer.postMessage(payload);
      return;
    }
    settled = true;
    cleanup();
    reject(new Error(i18n.t('errors.wxTransferNotSupported')));
  });
}

/** 切换宿主底部 tab（Android/iOS 原生 tab 索引）。非原生环境降级为 console.warn。 */
export function switchTab(index: number): void {
  if (window.NativeBridge?.switchTab) {
    window.NativeBridge.switchTab(index);
    return;
  }
  if (window.webkit?.messageHandlers?.switchTab) {
    window.webkit.messageHandlers.switchTab.postMessage({ index });
    return;
  }
  console.warn('[bridge] switchTab not supported in this env');
}

export function goBack(): void {
  if (window.NativeBridge?.goBack) {
    window.NativeBridge.goBack();
    return;
  }
  if (window.webkit?.messageHandlers?.goBack) {
    window.webkit.messageHandlers.goBack.postMessage({});
    return;
  }
  window.history.back();
}

/** @deprecated 使用 showRewardAd 替代 */
export function showAd(adType: string): void {
  if (window.NativeBridge?.showRewardAd) {
    window.NativeBridge.showRewardAd(adType);
    return;
  }
  if (window.webkit?.messageHandlers?.showRewardAd) {
    window.webkit.messageHandlers.showRewardAd.postMessage({ adType });
    return;
  }
  if (window.ReactNativeWebView) {
    window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'showAd', data: { adType } }));
  }
}
