/**
 * Flex gap polyfill for Chrome < 84 (e.g., Huawei Android 10 默认 WebView 83).
 * Feature-detects flex `gap` support; when missing, adds `no-flex-gap` on <html>
 * and applies margin-based fallbacks via MutationObserver.
 *
 * Covers both:
 *   - Tailwind `gap-*` classes (handled via CSS rules in index.css)
 *   - inline `style={{ gap: N }}` (handled here by walking flex children)
 *
 * Grid gap is untouched — Chrome 83 already supports grid gap.
 */

function supportsFlexGap(): boolean {
  try {
    const flex = document.createElement('div');
    flex.style.display = 'flex';
    flex.style.flexDirection = 'column';
    flex.style.rowGap = '1px';
    flex.appendChild(document.createElement('div'));
    flex.appendChild(document.createElement('div'));
    document.body.appendChild(flex);
    const ok = flex.scrollHeight === 1;
    flex.parentNode?.removeChild(flex);
    return ok;
  } catch {
    return true;
  }
}

function parsePx(value: string): string | null {
  const m = value.match(/^\s*(\d+(?:\.\d+)?)(px|rem|em)?\s*$/);
  if (!m) return null;
  const unit = m[2] || 'px';
  return m[1] + unit;
}

function applyFallbackToEl(el: HTMLElement): void {
  const gap = el.style.gap || el.style.rowGap || el.style.columnGap;
  if (!gap) return;
  const cs = getComputedStyle(el);
  const display = cs.display;
  if (display !== 'flex' && display !== 'inline-flex') return;
  const flexDir = cs.flexDirection;
  const value = parsePx(gap);
  if (!value) return;

  const isCol = flexDir === 'column' || flexDir === 'column-reverse';
  const children = Array.from(el.children) as HTMLElement[];
  children.forEach((child, idx) => {
    if (idx === 0) return;
    if (isCol) {
      if (child.dataset.polyfillMt !== value) {
        child.style.marginTop = value;
        child.dataset.polyfillMt = value;
      }
    } else {
      if (child.dataset.polyfillMl !== value) {
        child.style.marginLeft = value;
        child.dataset.polyfillMl = value;
      }
    }
  });
}

function sweep(root: ParentNode): void {
  const nodes = root.querySelectorAll<HTMLElement>('[style*="gap"]');
  nodes.forEach(applyFallbackToEl);
}

export function installFlexGapPolyfill(): void {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  const run = (): void => {
    if (supportsFlexGap()) return;
    document.documentElement.classList.add('no-flex-gap');

    sweep(document.body);

    const observer = new MutationObserver((mutations) => {
      for (const m of mutations) {
        if (m.type === 'childList') {
          m.addedNodes.forEach((node) => {
            if (node.nodeType === 1) sweep(node as Element);
          });
        } else if (m.type === 'attributes' && m.target.nodeType === 1) {
          const target = m.target as HTMLElement;
          if (target.style && (target.style.gap || target.style.rowGap || target.style.columnGap)) {
            applyFallbackToEl(target);
          }
        }
      }
    });
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['style'],
    });
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run, { once: true });
  } else {
    run();
  }
}
