import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft } from 'lucide-react';
import MacroGrid from '../../components/MacroGrid';
import { dietApi } from '../../api/diet';
import type { ProfileDisplay } from '../../api/diet';
import { useDietPageTracking, trackDietClick, DietPages } from '../../utils/tracking';

const GOAL_LABEL: Readonly<Record<string, string>> = { lose_weight: '减脂', gain_weight: '增肌', keep: '保持', maintain: '保持' };
const ACTIVITY_LABEL: Readonly<Record<string, string>> = {
  sedentary: '久坐',
  light: '轻度活动',
  moderate: '中度活动',
  active: '高强度',
};

/**
 * 设定每日目标（设计稿 1:2289）。展示身体数据 + 当前 BMI + 每日推荐摄入。
 * 数据为占位，接口接通后由后端计算返回。重新设定/确定目标。
 */
export default function GoalDaily() {
  useDietPageTracking(DietPages.goalDaily);
  const navigate = useNavigate();
  const [profile, setProfile] = useState<ProfileDisplay | null>(null);

  useEffect(() => {
    dietApi.getProfileDisplay().then(setProfile).catch(() => setProfile(null));
  }, []);

  const p = profile?.user_profile;
  const body: readonly (readonly [string, string])[] = [
    ['年龄', p ? `${p.age}岁` : '25岁'],
    ['体重', p ? `${p.current_weight_kg}kg` : '52kg'],
    ['理想体重', p ? `${p.target_weight_kg}kg` : '47kg'],
    ['身高', p ? `${p.height_cm}cm` : '160cm'],
    ['目标', p ? GOAL_LABEL[p.goal_type] ?? p.goal_type : '减脂'],
    ['运动情况', p ? ACTIVITY_LABEL[p.activity_level] ?? p.activity_level : '中度活动'],
  ];
  const bmi = profile?.bmi_analysis.value ?? 21.4;
  const bmiLabel = profile?.bmi_analysis.status_label ?? '理想';
  const bmiPct = Math.max(0, Math.min(1, (bmi - 14) / (32 - 14))); // 14~32 映射
  const recommend = profile?.recommendation.daily_calories_kcal ?? 2040;
  const rec = profile?.recommendation.nutrients;
  const macroCells = [
    { label: '碳水', value: `${rec ? Math.round(rec.carbohydrates_g) : 270}克` },
    { label: '蛋白质', value: `${rec ? Math.round(rec.protein_g) : 92}克` },
    { label: '脂肪', value: `${rec ? Math.round(rec.fat_g) : 63}克` },
  ];

  return (
    <div className="min-h-screen bg-[#F0F2F4]">
      <div style={{ paddingTop: 'var(--status-bar-height, env(safe-area-inset-top, 0px))' }}>
        <header className="relative h-14">
          <button onClick={() => { trackDietClick(DietPages.goalDaily, 'back'); navigate(-1); }} className="absolute left-2 top-1/2 grid h-9 w-9 -translate-y-1/2 place-items-center" aria-label="返回">
            <ChevronLeft size={22} className="text-[#1A1A1A]" />
          </button>
          <div className="flex h-full items-center justify-center text-lg font-semibold text-black">设定每日目标</div>
        </header>

        <div className="px-4 pb-32 pt-2">
          {/* 身体数据 */}
          <section className="rounded-xl bg-white px-4 py-4">
            <div className="mb-3 text-[15px] font-semibold text-[#1A1A1A]">我的身体数据</div>
            <div className="grid grid-cols-3 gap-y-4">
              {body.map(([k, v]) => (
                <div key={k}>
                  <div className="text-xs text-[#999]">{k}</div>
                  <div className="mt-0.5 text-sm font-semibold text-[#1A1A1A]">{v}</div>
                </div>
              ))}
            </div>
          </section>

          {/* BMI */}
          <section className="mt-3 rounded-xl bg-white px-4 py-4">
            <div className="text-xs text-[#999]">当前BMI为</div>
            <div className="mt-1 flex items-center gap-2">
              <span className="text-[34px] font-extrabold leading-none text-[#1A1A1A]">{bmi}</span>
              <span className="rounded-full bg-[#E8F5E9] px-2 py-0.5 text-xs font-medium text-[#22C55E]">{bmiLabel}</span>
            </div>
            <div className="relative mt-4 h-2 rounded-full" style={{ background: 'linear-gradient(90deg,#5AC8FA,#22C55E,#FBBF24,#F76133)' }}>
              <div className="absolute -top-1.5 h-5 w-1 -translate-x-1/2 rounded bg-[#1A1A1A]" style={{ left: `${bmiPct * 100}%` }} />
            </div>
            <div className="mt-2 flex justify-between text-[11px] text-[#999]">
              <span>偏瘦</span>
              <span>理想</span>
              <span>偏胖</span>
              <span>肥胖</span>
            </div>
            <p className="mt-3 text-xs leading-relaxed text-[#999]">
              BMI 是身体质量指数的缩写，一种用来估算人体胖瘦程度的常用指标，计算方法是体重(千克)除以身高(米)的平方。
            </p>
          </section>

          {/* 推荐摄入 */}
          <section className="mt-3 rounded-xl bg-white px-4 py-4">
            <div className="text-xs text-[#999]">每日推荐摄入</div>
            <div className="mt-1 flex items-baseline gap-1">
              <span className="text-[34px] font-extrabold leading-none text-[#1A1A1A]">{recommend}</span>
              <span className="text-sm font-medium text-[#999]">KCAL</span>
            </div>
            <div className="mt-4">
              <MacroGrid cells={macroCells} />
            </div>
          </section>
        </div>
      </div>

      <div className="fixed inset-x-0 bottom-0 flex gap-3 bg-gradient-to-t from-[#F0F2F4] px-4 pt-3" style={{ paddingBottom: 'calc(env(safe-area-inset-bottom) + 16px)' }}>
        <button onClick={() => { trackDietClick(DietPages.goalDaily, 'reset'); navigate('/goal'); }} className="h-12 flex-1 rounded-full border border-[#E5E6E8] text-sm font-medium text-[#1A1A1A]">
          重新设定
        </button>
        <button
          onClick={() => { trackDietClick(DietPages.goalDaily, 'confirm'); navigate('/'); }}
          className="h-12 flex-1 rounded-full text-sm font-medium text-white"
          style={{ background: 'linear-gradient(90deg,#F75C36,#FB8C18)' }}
        >
          确定目标
        </button>
      </div>
    </div>
  );
}
