import React from 'react';
import ReactDOM from 'react-dom/client';
// file:// 环境下 BrowserRouter 的 pushState 不可用，用 HashRouter 保证导航稳定
import { HashRouter } from 'react-router-dom';
// 分包入口：构建期由 vite.config 的 `@active-app` 别名按 VITE_APP 解析到
// src/apps/spark（默认，福利社）或 src/apps/diet（饮食热量）。未选中的 app 不进依赖图。
import App from '@active-app';
import { installDevMock } from './utils/devMock';
import { installFlexGapPolyfill } from './utils/flexGapPolyfill';
// 海外上线:初始化 i18next。客户端在 document_start 注入 __APP_LOCALE__,
// 否则按 navigator.language 兜底。必须放在 App 渲染前。
import './locales';
import './index.css';

installDevMock();
installFlexGapPolyfill();

// 华为 Android 10 Chrome 83 WebView 的 compositor focus ring（橙色粗框）CSS outline:none
// 压不掉。点击后立即 blur 当前焦点元素，使 :focus 状态消失。
document.addEventListener('click', () => {
  const el = document.activeElement;
  if (el && el !== document.body && 'blur' in el) {
    (el as HTMLElement).blur();
  }
}, true);

const root = document.getElementById('root');

if (root) {
  ReactDOM.createRoot(root).render(
    <React.StrictMode>
      <HashRouter>
        <App />
      </HashRouter>
    </React.StrictMode>,
  );
}
