interface CalorieRingProps {
  /** 进度 0~1，从顶部逆时针填充（橙在左+底） */
  readonly progress: number;
  readonly size?: number;
  readonly stroke?: number;
  readonly children?: React.ReactNode;
}

/** 角度→坐标。0=顶部(12点)，逆时针为正（90=左/9点，180=底/6点，270=右/3点） */
function pointAt(cx: number, cy: number, r: number, deg: number): [number, number] {
  const rad = (deg * Math.PI) / 180;
  return [cx - r * Math.sin(rad), cy - r * Math.cos(rad)];
}

/**
 * 热量进度圆环。设计稿 1:2957：完整灰轨 #F4F4F5 + 橘红→琥珀渐变弧(#F9552A→#FB8D18)，
 * 从顶部 12 点逆时针扫(橙在左+底)，两端圆头。
 * 用折线采样逐点画弧，方向完全可控（避免 SVG arc flag / transform 镜像歧义）。
 */
export default function CalorieRing({ progress, size = 180, stroke = 14, children }: CalorieRingProps) {
  const p = Math.max(0, Math.min(1, progress));
  const r = (size - stroke) / 2;
  const cx = size / 2;
  const cy = size / 2;

  const end = p * 360;
  const step = 2;
  const pts: string[] = [];
  for (let a = 0; a <= end; a += step) {
    const [x, y] = pointAt(cx, cy, r, a);
    pts.push(`${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  if (end > 0) {
    const [x, y] = pointAt(cx, cy, r, end);
    pts.push(`${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  const arcPath = pts.length ? `M ${pts.join(' L ')}` : '';

  return (
    <div className="relative" style={{ width: size, height: size }}>
      <svg width={size} height={size}>
        <defs>
          <linearGradient id="diet-ring" x1="50%" y1="0%" x2="50%" y2="100%">
            <stop offset="0%" stopColor="#F9552A" />
            <stop offset="100%" stopColor="#FB8D18" />
          </linearGradient>
        </defs>
        <circle cx={cx} cy={cy} r={r} fill="none" stroke="#F4F4F5" strokeWidth={stroke} />
        {arcPath && (
          <path
            d={arcPath}
            fill="none"
            stroke="url(#diet-ring)"
            strokeWidth={stroke}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        )}
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">{children}</div>
    </div>
  );
}
