import { Routes, Route, Navigate } from 'react-router-dom';
import { useEffect, useState } from 'react';
import Loading from '@/components/Loading';
import { useUserStore } from '@/store/useUserStore';
import { ensureDietDevToken } from './api/client';
import DietHome from './pages/home';
import GoalInfo from './pages/goal';
import GoalDaily from './pages/goal/Daily';
import DietCalendar from './pages/calendar';

/**
 * 饮食热量 app 根组件。独立 SPA，根路径即主页（不挂福利社的底部 Tab Layout）。
 *
 * 鉴权说明：diet 用自己的后端独立鉴权（user_id 字段直接传 microLife JWT）。
 *   - 端侧注入 token（iOS appendH5QueryItems / Android attachToken）：URL 自带 ?token=，直接用
 *   - PC 浏览器 dev 调试：调 `ensureDietDevToken()` 自动用测试账号 mint token 缓存
 *     （模仿福利社 useUserStore.mintDevToken；账号在 .env.development.local，git ignored）
 *
 * 路由表：
 *   /            主页（热量圈 + 分餐记录）；记录饮食/编辑/修改时间/自定义热量为弹层
 *   /goal        设定目标-填身体信息（两步）
 *   /goal/daily  设定目标-每日目标
 *   /calendar    打卡日历
 */
export default function DietApp() {
  const initFromQuery = useUserStore((s) => s.initFromQuery);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    // PC 浏览器 dev：先尝试自动 mint diet token 缓存，无端侧/URL 注入时也能调真接口
    // 端侧/URL 注入了：走 spark 老流程 initFromQuery 写 token（保持兼容）
    const params = new URLSearchParams(window.location.search);
    const hasSparkToken = !!window.__SPARK_INIT__ || params.has('token') || params.has('dev');
    Promise.all([
      ensureDietDevToken(),
      hasSparkToken ? initFromQuery() : Promise.resolve(),
    ]).finally(() => setReady(true));
  }, [initFromQuery]);

  if (!ready) return <Loading />;

  return (
    <Routes>
      <Route index element={<DietHome />} />
      <Route path="goal" element={<GoalInfo />} />
      <Route path="goal/daily" element={<GoalDaily />} />
      <Route path="calendar" element={<DietCalendar />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}
