import { useEffect } from 'react';
import { X, ChevronDown } from 'lucide-react';
import BottomSheet from './BottomSheet';
import MacroGrid from './MacroGrid';
import type { MealGroup } from '../types';
import { MEAL_LABEL } from '../types';
import { trackEvent, ActionType, setCurrentPage } from '@/utils/tracker';
import { trackDietClick, DietPages } from '../utils/tracking';

interface RecordEditSheetProps {
  readonly open: boolean;
  readonly group: MealGroup | null;
  readonly date: string;
  readonly onClose: () => void;
  readonly onDelete: () => void;
}

/**
 * 记录编辑弹层（设计稿 1:3375）。
 * 顶部：删除 / 日期+餐别▾ / 关闭；中部食物列表；底部三宫格。
 */
export default function RecordEditSheet({ open, group, date, onClose, onDelete }: RecordEditSheetProps) {
  // enter/exit 埋点(group 不为 null 时弹层可见 = open)
  useEffect(() => {
    if (!open || !group) return;
    setCurrentPage(DietPages.recordEdit);
    trackEvent(ActionType.ENTER, `${DietPages.recordEdit}_enter`, DietPages.recordEdit);
    return () => {
      trackEvent(ActionType.EXIT, `${DietPages.recordEdit}_exit`, DietPages.recordEdit);
    };
  }, [open, group]);

  if (!group) return null;
  return (
    <BottomSheet open={open} onClose={onClose}>
      <div className="px-4 pb-5 pt-4">
        <div className="mb-4 flex items-center justify-between">
          <button onClick={() => { trackDietClick(DietPages.recordEdit, 'delete', { meal: group.meal, count: group.records.length }); onDelete(); }} className="text-sm text-[#999]">
            删除
          </button>
          <div className="flex items-center gap-1">
            <span className="text-base font-semibold text-[#1A1A1A]">
              {date} {MEAL_LABEL[group.meal]}
            </span>
            <ChevronDown size={16} className="text-[#999]" />
          </div>
          <button onClick={() => { trackDietClick(DietPages.recordEdit, 'close'); onClose(); }} aria-label="关闭">
            <X size={20} className="text-[#1A1A1A]" />
          </button>
        </div>

        <div className="mb-3">
          {group.records.map((r) => (
            <div key={r.id} className="flex items-center gap-3 py-2.5">
              <div className="h-12 w-12 shrink-0 rounded-xl bg-[#F0F0F0]">
                {r.imageUrl ? <img src={r.imageUrl} alt={r.name} className="h-full w-full rounded-xl object-cover" /> : null}
              </div>
              <div className="min-w-0 flex-1">
                <div className="truncate text-[15px] font-medium text-[#2F2E2E]">{r.name}</div>
                <div className="text-xs text-[#A1A1AA]">{r.portion}</div>
              </div>
              <div className="text-base font-bold text-[#2F2E2E]">
                {r.calorie} <span className="text-xs font-normal text-[#A1A1AA]">kcal</span>
              </div>
            </div>
          ))}
        </div>

        <MacroGrid
          cells={[
            { label: '碳水', value: `${group.macro.carb}克` },
            { label: '蛋白质', value: `${group.macro.protein}克` },
            { label: '脂肪', value: `${group.macro.fat}克` },
          ]}
        />
      </div>
    </BottomSheet>
  );
}
