/**
 * 福利页 H5 埋点上报客户端。
 * 规则：.claude/skills/auto-tracking/SKILL.md
 *
 * 公共参数优先级：
 *   端侧 JSBridge（android_common.getTrackingCommonInfo / WearfitBridge.getTrackingCommonInfo）
 * → 端侧预注入 window.__NATIVE_COMMON__
 * → H5 自采（__SPARK_INIT__ + UA 解析 + localStorage）
 *
 * 上报协议对齐 test-collection 的 tracker：批量缓存 + 5s flush + beforeunload 冲刷。
 */

declare const __APP_VERSION__: string | undefined;
declare const __APP_ID__: string | undefined;

const TRACKING_API = (() => {
  // 测试环境：使用测试域名；非测试走正式 & mock（由 client.ts 的 baseURL 判断同理）
  const env = (window as unknown as { __SPARK_INIT__?: { env?: string } }).__SPARK_INIT__?.env
    ?? new URLSearchParams(window.location.search).get('env')
    ?? 'pro';
  if (env === 'sit') return 'https://test-ai-howear.iwhop.cn/howeartest/microLife/tracking/push';
  // 海外上线:客户端注入 __IS_OVERSEAS__ 时埋点上报到海外域名
  const isOverseas = (window as unknown as { __IS_OVERSEAS__?: boolean }).__IS_OVERSEAS__ === true;
  return isOverseas
    ? 'https://micro-life.iwhop.com/microLife/tracking/push'
    : 'https://micro-life.iwhop.cn/microLife/tracking/push';
})();

interface CommonInfo {
  userId: string;
  eId: string;
  appVersion: string;
  os: string;
  osVersion: string;
  businessType: string;
  model: string;
  networkType: string;
  channelId: string;
  appId: string;
  sessionID: string;
  launchID: string;
  areaType: string;
  expIds: string;
  [key: string]: unknown;
}

interface BuryPointEvent {
  actionId: string;
  actionType: string;
  actionName: string;
  pageId: string;
  sourcePageId: string;
  currTime: number;
  extend: Record<string, unknown>;
  common: CommonInfo;
}

let eventCache: BuryPointEvent[] = [];
let timer: ReturnType<typeof setInterval> | null = null;
let nativeCommonCache: CommonInfo | null = null;

const sessionID = `s_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
const launchID = `l_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

// ============================================================
// 端侧 JSBridge
// ============================================================

function isInApp(): boolean {
  const ua = navigator.userAgent;
  return (
    typeof (window as unknown as Record<string, unknown>)['android_common'] !== 'undefined'
    || typeof (window as unknown as Record<string, unknown>)['WearfitBridge'] !== 'undefined'
    || /WearfitPro/i.test(ua)
    // Spark 福利壳也认为是在 App 内
    || typeof (window as unknown as Record<string, unknown>)['__SPARK_INIT__'] !== 'undefined'
  );
}

function getNativeCommon(): CommonInfo | null {
  if (nativeCommonCache) return nativeCommonCache;
  try {
    let jsonStr: string | null = null;
    const w = window as unknown as {
      android_common?: { getTrackingCommonInfo?: () => string };
      WearfitBridge?: { getTrackingCommonInfo?: () => string };
      __NATIVE_COMMON__?: CommonInfo;
    };
    if (w.android_common?.getTrackingCommonInfo) {
      jsonStr = w.android_common.getTrackingCommonInfo();
    }
    if (!jsonStr && w.WearfitBridge?.getTrackingCommonInfo) {
      jsonStr = w.WearfitBridge.getTrackingCommonInfo();
    }
    if (!jsonStr && w.__NATIVE_COMMON__) {
      nativeCommonCache = w.__NATIVE_COMMON__;
      return nativeCommonCache;
    }
    if (jsonStr) {
      nativeCommonCache = JSON.parse(jsonStr) as CommonInfo;
      return nativeCommonCache;
    }
  } catch {
    // bridge 调用失败，走降级
  }
  return null;
}

// ============================================================
// H5 自采公参（端侧无 bridge 时兜底）
// ============================================================

function readSparkInit<K extends string>(key: K): string {
  const w = window as unknown as { __SPARK_INIT__?: Record<string, string | undefined> };
  const fromWindow = w.__SPARK_INIT__?.[key];
  if (fromWindow) return fromWindow;
  try {
    const p = new URLSearchParams(window.location.search);
    const v = p.get(key);
    return v ? decodeURIComponent(v) : '';
  } catch {
    return '';
  }
}

const DEVICE_ID_KEY = 'spark-eid';

function getOrCreateDeviceId(): string {
  let eid = localStorage.getItem(DEVICE_ID_KEY);
  if (eid) return eid;
  eid = `e_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
  try { localStorage.setItem(DEVICE_ID_KEY, eid); } catch { /* ignore */ }
  return eid;
}

function getOS(ua: string): string {
  if (/android/i.test(ua)) return 'Android';
  if (/iPad|iPhone|iPod/i.test(ua)) return 'iOS';
  if (/Windows/i.test(ua)) return 'Windows';
  if (/Mac/i.test(ua)) return 'macOS';
  return 'unknown';
}

function getOSVersion(ua: string): string {
  const android = ua.match(/Android\s([\d.]+)/);
  if (android) return android[1];
  const ios = ua.match(/OS\s([\d_]+)/);
  if (ios) return ios[1].replace(/_/g, '.');
  return '';
}

function getModel(ua: string): string {
  const android = ua.match(/;\s*([^;)]+)\s*Build\//);
  if (android) return android[1].trim();
  if (/iPad/i.test(ua)) return 'iPad';
  if (/iPhone/i.test(ua)) return 'iPhone';
  return 'web';
}

function getNetworkType(): string {
  const conn = (navigator as unknown as { connection?: { effectiveType?: string } }).connection;
  return conn?.effectiveType ?? 'unknown';
}

const CHANNEL_KEY = 'spark-channel';
function getChannelId(): string {
  const params = new URLSearchParams(window.location.search);
  const ch = params.get('channel') ?? params.get('ch');
  if (ch) {
    try { localStorage.setItem(CHANNEL_KEY, ch); } catch { /* ignore */ }
    return ch;
  }
  return localStorage.getItem(CHANNEL_KEY) ?? 'H5';
}

function getAreaType(): string {
  const lang = navigator.language || '';
  return /^zh/i.test(lang) ? '1' : '2';
}

function getH5CommonInfo(): CommonInfo {
  const ua = navigator.userAgent;
  return {
    userId: readSparkInit('uid') || '',
    eId: getOrCreateDeviceId(),
    appVersion: (typeof __APP_VERSION__ !== 'undefined' ? __APP_VERSION__ : '') || readSparkInit('appVersion') || '1.0.0',
    os: readSparkInit('platform').toLowerCase() === 'android' ? 'Android'
      : readSparkInit('platform').toLowerCase() === 'ios' ? 'iOS'
      : getOS(ua),
    osVersion: getOSVersion(ua),
    businessType: 'h5',
    model: getModel(ua),
    networkType: getNetworkType(),
    channelId: getChannelId(),
    // 与 wearfitpro 主 App 对齐：WP + native source 在 iOS WKDataAnalyticsSource 里也是 ""
    // H5 自采兜底（端外/无桥）也保持空，避免数据团队聚合时把福利当作独立 App
    appId: typeof __APP_ID__ !== 'undefined' ? __APP_ID__ : '',
    sessionID,
    launchID,
    areaType: getAreaType(),
    expIds: '',
  };
}

function getCommonInfo(): CommonInfo {
  if (isInApp()) {
    const native = getNativeCommon();
    if (native) {
      // 端侧可能缺 sessionID/launchID，补一下
      return {
        ...native,
        sessionID: native.sessionID || sessionID,
        launchID: native.launchID || launchID,
      };
    }
  }
  return getH5CommonInfo();
}

// ============================================================
// 批处理 & 上报
// ============================================================

function generateActionId(): string {
  const r = Math.floor(1000 + Math.random() * 9000);
  return `${Date.now()}${r}`;
}

function flushEvents(): void {
  if (eventCache.length === 0) return;
  const events = [...eventCache];
  eventCache = [];
  fetch(TRACKING_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(events),
    keepalive: true,
  }).catch(() => {
    // 失败回滚到队列，下次再发
    eventCache.unshift(...events);
  });
}

function startTimer(): void {
  if (timer) return;
  timer = setInterval(flushEvents, 5000);
}

// ============================================================
// 公开 API
// ============================================================

export const ActionType = {
  ENTER: 'enter',
  EXIT: 'exit',
  CLICK: 'click',
  EXPOSURE: 'exposure',
  SHOW: 'show',
  CLOSE: 'close',
  SCROLL: 'scroll',
  REQUEST: 'request',
  DATA_LOAD: 'data_load',
  BACK: 'back',
  LOSE: 'lose',
  PLAY_START: 'playStart',
} as const;

export type ActionTypeValue = typeof ActionType[keyof typeof ActionType];

/** 常驻当前路由 pageId — 由 usePageTracker 维护 */
let currentPageId = '';
let previousPageId = '';

export function setCurrentPage(pageId: string): void {
  if (pageId === currentPageId) return;
  previousPageId = currentPageId;
  currentPageId = pageId;
}

export function trackEvent(
  actionType: ActionTypeValue | string,
  actionName: string,
  pageId: string = currentPageId,
  extend: Record<string, unknown> = {},
  sourcePageId: string = previousPageId,
): void {
  const event: BuryPointEvent = {
    actionId: generateActionId(),
    actionType,
    actionName,
    pageId,
    sourcePageId,
    currTime: Date.now(),
    extend,
    common: getCommonInfo(),
  };
  eventCache.push(event);
  startTimer();
}

/** 关键事件（如支付/提现/领取）立即上报，不等 flush */
export function trackImmediate(
  actionType: ActionTypeValue | string,
  actionName: string,
  pageId: string = currentPageId,
  extend: Record<string, unknown> = {},
  sourcePageId: string = previousPageId,
): void {
  const event: BuryPointEvent = {
    actionId: generateActionId(),
    actionType,
    actionName,
    pageId,
    sourcePageId,
    currTime: Date.now(),
    extend,
    common: getCommonInfo(),
  };
  fetch(TRACKING_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify([event]),
    keepalive: true,
  }).catch(() => {
    eventCache.push(event);
  });
}

/** 用户登录 / 切换账号后刷新端侧公参 */
export function refreshNativeCommon(): void {
  nativeCommonCache = null;
}

/** 调试用：拿当前公参 */
export function peekCommonInfo(): CommonInfo {
  return getCommonInfo();
}

if (typeof window !== 'undefined') {
  window.addEventListener('beforeunload', () => {
    flushEvents();
    if (timer) clearInterval(timer);
    timer = null;
  });
  window.addEventListener('pagehide', flushEvents);
  // 暴露到 window 方便端侧/控制台验证
  (window as unknown as { __sparkTracker?: unknown }).__sparkTracker = {
    peek: peekCommonInfo,
    flush: flushEvents,
    cache: () => eventCache,
  };
}
