import { useEffect, useRef, useState } from 'react';
import type { CSSProperties, ReactNode } from 'react';

interface MarqueeTextProps {
  readonly children: ReactNode;
  /** 滚动速度 px/秒,默认 50 */
  readonly speed?: number;
  /** 两份内容之间的视觉间距 px,默认 40 */
  readonly gap?: number;
  readonly className?: string;
  readonly style?: CSSProperties;
  /** inline=true 时容器用 inline-block,适合放在弟兄元素之间 */
  readonly inline?: boolean;
}

/**
 * 单行文本容器:
 *  - 内容能放下 → 静态展示(同普通 span,父容器宽度不受影响)
 *  - 内容溢出 → 无缝走马灯。轨道用 absolute 定位,**不撑大父容器** — 容器宽度
 *    依然由"原内容(单份)"决定,跟无 MarqueeText 时一致,只是溢出部分用动画
 *    平移展示。
 *
 * 兜底链(防字体晚加载导致首测宽偏小):
 *  1. mount 同步测一次 → 2. raf 下一帧测 → 3. document.fonts.ready 后测
 *  → 4. 100/500/2000ms 三档定时兜底 → 5. ResizeObserver 持续监听
 *  6. window.__SPARK_DEBUG_MARQUEE__ = true 可强制启用(调试用)
 */
export default function MarqueeText({
  children,
  speed = 50,
  gap = 40,
  className,
  style,
  inline = false,
}: MarqueeTextProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const sizerRef = useRef<HTMLSpanElement>(null);
  const [overflow, setOverflow] = useState(false);
  const [itemWidth, setItemWidth] = useState(0);

  useEffect(() => {
    const c = containerRef.current;
    const sizer = sizerRef.current;
    if (!c || !sizer) return;

    let disposed = false;
    const measure = () => {
      if (disposed) return;
      const cw = c.clientWidth;
      const iw = sizer.scrollWidth;
      const forced =
        typeof window !== 'undefined' &&
        (window as Window & { __SPARK_DEBUG_MARQUEE__?: boolean }).__SPARK_DEBUG_MARQUEE__ === true;
      setOverflow(forced || iw > cw + 1);
      setItemWidth(iw);
    };

    measure();
    const raf = requestAnimationFrame(measure);
    const fonts = (document as Document & { fonts?: { ready?: Promise<unknown> } }).fonts;
    fonts?.ready?.then(measure).catch(() => { /* ignore */ });
    const t1 = setTimeout(measure, 100);
    const t2 = setTimeout(measure, 500);
    const t3 = setTimeout(measure, 2000);
    const ro = new ResizeObserver(measure);
    ro.observe(c);
    ro.observe(sizer);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      clearTimeout(t1);
      clearTimeout(t2);
      clearTimeout(t3);
      ro.disconnect();
    };
  }, [children]);

  // 容器:inline 模式用 inline-block(随内容大小),否则 block 元素跟普通段落一样
  // 关键:**不再用 display:flex**,避免溢出分支撑大父容器。
  // overflow: hidden 让走马灯轨道(absolute)能被剪裁。
  const containerStyle: CSSProperties = {
    display: inline ? 'inline-block' : 'block',
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    position: 'relative',
    maxWidth: '100%',
    verticalAlign: inline ? 'middle' : undefined,
    ...style,
  };

  // sizer 永远渲染单份,决定容器的"自然宽度",不溢出时直接展示;溢出时 visibility:hidden
  // 但仍占空间,所以容器高度/对齐保持原样。
  const sizerStyle: CSSProperties = {
    display: 'inline-block',
    visibility: overflow ? 'hidden' : 'visible',
  };

  if (!overflow) {
    return (
      <div ref={containerRef} className={className} style={containerStyle}>
        <span ref={sizerRef} style={sizerStyle}>{children}</span>
      </div>
    );
  }

  // 溢出:轨道 absolute 浮在 sizer 上层,两份内容并排 + 无缝循环平移
  const distance = itemWidth + gap;
  const duration = Math.max(distance / speed, 4);

  const trackStyle: CSSProperties = {
    position: 'absolute',
    top: 0,
    left: 0,
    display: 'flex',
    alignItems: 'center',
    height: '100%',
    animation: `spark-marquee-loop ${duration}s linear infinite`,
    willChange: 'transform',
    ['--spark-marquee-distance' as string]: `-${distance}px`,
  };

  return (
    <div ref={containerRef} className={className} style={containerStyle}>
      {/* sizer 占位,保持容器高度同静态时一致 */}
      <span ref={sizerRef} style={sizerStyle}>{children}</span>
      {/* 走马灯轨道(浮在 sizer 上) */}
      <div style={trackStyle}>
        <span style={{ display: 'inline-block', paddingRight: gap }}>{children}</span>
        <span aria-hidden style={{ display: 'inline-block', paddingRight: gap }}>{children}</span>
      </div>
    </div>
  );
}
