import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import LanguageDetector from 'i18next-browser-languagedetector';

import zhCN from './zh-CN.json';
import zhTW from './zh-TW.json';
import enUS from './en-US.json';
import jaJP from './ja-JP.json';
import koKR from './ko-KR.json';
import esES from './es-ES.json';
import ptBR from './pt-BR.json';
import ptPT from './pt-PT.json';
import frFR from './fr-FR.json';
import deDE from './de-DE.json';
import ruRU from './ru-RU.json';
import arSA from './ar-SA.json';
import thTH from './th-TH.json';
import viVN from './vi-VN.json';
import idID from './id-ID.json';
import msMY from './ms-MY.json';
import trTR from './tr-TR.json';
import itIT from './it-IT.json';
import nlNL from './nl-NL.json';
import plPL from './pl-PL.json';
import hiIN from './hi-IN.json';

/** 客户端 window 注入的环境标识(Android/iOS 在 document_start 时写入) */
declare global {
  interface Window {
    __APP_REGION__?: 'overseas' | 'mainland';
    __APP_LOCALE__?: string;
    __IS_OVERSEAS__?: boolean;
  }
}

const resources = {
  'zh-CN': { translation: zhCN },
  'zh-TW': { translation: zhTW },
  'en-US': { translation: enUS },
  'ja-JP': { translation: jaJP },
  'ko-KR': { translation: koKR },
  'es-ES': { translation: esES },
  'pt-BR': { translation: ptBR },
  'pt-PT': { translation: ptPT },
  'fr-FR': { translation: frFR },
  'de-DE': { translation: deDE },
  'ru-RU': { translation: ruRU },
  'ar-SA': { translation: arSA },
  'th-TH': { translation: thTH },
  'vi-VN': { translation: viVN },
  'id-ID': { translation: idID },
  'ms-MY': { translation: msMY },
  'tr-TR': { translation: trTR },
  'it-IT': { translation: itIT },
  'nl-NL': { translation: nlNL },
  'pl-PL': { translation: plPL },
  'hi-IN': { translation: hiIN },
} as const;

/** 从 navigator.language 等候选转换为我们支持的 BCP 47 key */
function normalizeLocale(input: string | undefined): string {
  if (!input) return 'zh-CN';
  // 'zh' / 'zh-Hans' / 'zh_CN' → 'zh-CN'
  const lower = input.replace('_', '-').toLowerCase();
  if (lower.startsWith('zh-tw') || lower.startsWith('zh-hant')) return 'zh-TW';
  if (lower.startsWith('zh')) return 'zh-CN';
  if (lower.startsWith('en')) return 'en-US';
  if (lower.startsWith('ja')) return 'ja-JP';
  if (lower.startsWith('ko')) return 'ko-KR';
  if (lower.startsWith('es')) return 'es-ES';
  if (lower.startsWith('pt-br')) return 'pt-BR';
  if (lower.startsWith('pt')) return 'pt-PT';
  if (lower.startsWith('fr')) return 'fr-FR';
  if (lower.startsWith('de')) return 'de-DE';
  if (lower.startsWith('ru')) return 'ru-RU';
  if (lower.startsWith('ar')) return 'ar-SA';
  if (lower.startsWith('th')) return 'th-TH';
  if (lower.startsWith('vi')) return 'vi-VN';
  if (lower.startsWith('id')) return 'id-ID';
  if (lower.startsWith('ms')) return 'ms-MY';
  if (lower.startsWith('tr')) return 'tr-TR';
  if (lower.startsWith('it')) return 'it-IT';
  if (lower.startsWith('nl')) return 'nl-NL';
  if (lower.startsWith('pl')) return 'pl-PL';
  if (lower.startsWith('hi')) return 'hi-IN';
  return 'en-US'; // 不识别走英文兜底
}

const initialLocale = normalizeLocale(
  window.__APP_LOCALE__ || navigator.language,
);

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources,
    lng: initialLocale,
    fallbackLng: ['en-US', 'zh-CN'],
    interpolation: { escapeValue: false },
    detection: {
      order: ['querystring', 'navigator'],
      lookupQuerystring: 'lang',
    },
    // dev 模式下控制台 warn 缺失 key,生产静默
    saveMissing: import.meta.env.DEV,
    missingKeyHandler: (lngs, _ns, key) => {
      if (import.meta.env.DEV) {
        // eslint-disable-next-line no-console
        console.warn(`[i18n] missing key "${key}" for ${lngs.join(',')}`);
      }
    },
  });

/** 是否海外环境:客户端注入优先,否则按非中文区域推断 */
export const isOverseas: boolean =
  window.__IS_OVERSEAS__ === true ||
  window.__APP_REGION__ === 'overseas' ||
  (window.__IS_OVERSEAS__ === undefined &&
    window.__APP_REGION__ === undefined &&
    !initialLocale.startsWith('zh'));

export default i18n;
