import { useEffect } from 'react';

interface BottomSheetProps {
  readonly open: boolean;
  readonly onClose: () => void;
  /** true=占满大半屏（记录饮食）；false=自适应高度（编辑/自定义热量等） */
  readonly full?: boolean;
  readonly children: React.ReactNode;
}

/**
 * 通用底部弹层：半透明遮罩 + 白色圆角顶部面板，从底部滑入。
 * 设计稿统一弹层样式：圆角 20，遮罩点击关闭。
 */
export default function BottomSheet({ open, onClose, full = false, children }: BottomSheetProps) {
  useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, [open]);

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex flex-col justify-end">
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />
      <div
        className={`relative animate-[diet-sheet-up_220ms_ease-out] rounded-t-[20px] bg-white ${
          full ? 'h-[88vh]' : 'max-h-[88vh]'
        }`}
        style={{ paddingBottom: 'env(safe-area-inset-bottom)' }}
      >
        {children}
      </div>
      <style>{`@keyframes diet-sheet-up{from{transform:translateY(100%)}to{transform:translateY(0)}}`}</style>
    </div>
  );
}
