import { create } from 'zustand';

const TOKEN_STORAGE_KEY = 'spark-token';
const TOKEN_UID_KEY = 'spark-token-uid';
const DEV_TOKEN_ENDPOINT = '/api/v1/dev/token';

interface SparkInit {
  readonly uid?: string;
  readonly token?: string;
  readonly platform?: string;
  readonly env?: string;
  readonly appVersion?: string;
  readonly baseUrl?: string;
  /** '1' 表示需要渲染返回按钮（独立入口如视频 tab 金币浮球 push 进来）；默认不显示 */
  readonly showBack?: string;
}

declare global {
  interface Window {
    __SPARK_INIT__?: SparkInit;
  }
}

/**
 * 优先用 iOS WKWebView 注入的 `window.__SPARK_INIT__`；
 * 兜底 URL query（Android / 浏览器）。
 */
function readInitParam(key: keyof SparkInit): string | null {
  const fromWindow = window.__SPARK_INIT__?.[key];
  if (fromWindow) return fromWindow;
  try {
    const p = new URLSearchParams(window.location.search);
    const v = p.get(key);
    if (v) return decodeURIComponent(v);
  } catch {
    // ignore
  }
  return null;
}

/**
 * 后端绝对地址：file:// 下相对 URL 会解析成 file:///api/... 导致 404；
 * 必须从原生注入拿（WKUserScript / Android attachToken）；浏览器调试时回退到 VITE_API_BASE_URL。
 */
function resolveBackendBase(): string {
  const base = readInitParam('baseUrl');
  if (base) return base.replace(/\/+$/, '');
  const fromEnv = import.meta.env.VITE_API_BASE_URL as string | undefined;
  if (fromEnv) return fromEnv.replace(/\/+$/, '');
  return '';
}

interface UserState {
  readonly token: string;
  readonly deviceId: string;
  readonly platform: string;
  readonly appVersion: string;
  readonly env: string;
  readonly setToken: (token: string) => void;
  readonly clearToken: () => void;
  readonly initFromQuery: () => Promise<void>;
}

/**
 * 本地联调：App 传 `dev=1&uid=<uid>` → H5 向本地后端 /dev/token 换一个本地签名的 JWT。
 * 生产：App 传 `token=<realJwt>` → 直接使用，跳过 dev 换 token 流程。
 */
async function mintDevToken(uid: string): Promise<string> {
  const base = resolveBackendBase();
  const res = await fetch(`${base}${DEV_TOKEN_ENDPOINT}?uid=${encodeURIComponent(uid)}`);
  const json = await res.json();
  if (json?.code !== 200 || !json?.data?.token) {
    throw new Error(json?.message ?? 'dev token failed');
  }
  return json.data.token as string;
}

async function resolveToken(params: URLSearchParams): Promise<string> {
  // 1. 主 App 注入 token → 直接用
  //    - test/prod：Android BenefitsFragment.attachToken / iOS WKBenefitsHomeViewController 传 token=<UserDao.getToken()>
  //    - spark 后端与 micro-life 共享 JWT secret，能直接验签
  const injected = readInitParam('token');
  if (injected) return injected;
  const urlToken = params.get('token');
  if (urlToken) return urlToken;

  // 2. dev/local 模式：按 uid mint /dev/token（spark 后端 @Profile("dev") 才注册此接口）
  //    - mobile WebView：本地联调 URL `?dev=1&uid=<uid>` 或 window.__SPARK_INIT__
  //    - PC 浏览器调试（VITE_ENV=local 且没有任何参数和原生注入）：默认 dev=1 + uid=1001
  const envLocal = import.meta.env.VITE_ENV === 'local';
  const hasNativeInject = !!window.__SPARK_INIT__;
  const hasUrlParams = params.has('uid') || params.has('dev') || params.has('token');
  const isPcBrowserDebug = envLocal && !hasNativeInject && !hasUrlParams;
  const dev = params.get('dev') === '1' || isPcBrowserDebug;
  const uid = readInitParam('uid') ?? params.get('uid') ?? (isPcBrowserDebug ? '1001' : null);
  if (dev && uid) {
    // PC 浏览器调试永远 mint 新 token —— 后端 JWT secret 可能切过，旧 token 会 401
    if (!isPcBrowserDebug) {
      const cachedUid = localStorage.getItem(TOKEN_UID_KEY);
      if (cachedUid === uid) {
        const storageToken = localStorage.getItem(TOKEN_STORAGE_KEY);
        if (storageToken) return storageToken;
      }
    }
    try {
      const token = await mintDevToken(uid);
      localStorage.setItem(TOKEN_UID_KEY, uid);
      return token;
    } catch {
      return '';
    }
  }

  // 3. 非 dev：可以复用 localStorage
  const storageToken = localStorage.getItem(TOKEN_STORAGE_KEY);
  return storageToken ?? '';
}

export const useUserStore = create<UserState>((set) => ({
  token: '',
  deviceId: '',
  platform: '',
  appVersion: '',
  env: '',

  setToken: (token: string) => {
    if (token) {
      localStorage.setItem(TOKEN_STORAGE_KEY, token);
    } else {
      localStorage.removeItem(TOKEN_STORAGE_KEY);
    }
    set({ token });
  },

  clearToken: () => {
    localStorage.removeItem(TOKEN_STORAGE_KEY);
    set({ token: '' });
  },

  initFromQuery: async () => {
    const params = new URLSearchParams(window.location.search);
    const token = await resolveToken(params);
    const deviceId = readInitParam('uid') ?? params.get('deviceId') ?? '';
    const platform = readInitParam('platform') ?? params.get('platform') ?? '';
    const appVersion = readInitParam('appVersion') ?? params.get('appVersion') ?? '';
    const env = readInitParam('env') ?? params.get('env') ?? '';

    if (token) localStorage.setItem(TOKEN_STORAGE_KEY, token);
    set({ token, deviceId, platform, appVersion, env });
  },
}));
